window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-120"]=[{"id":"set2-Hd4JJjDl","fingerprint":"c839531749945d05","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt caracteristicile epidemiologice ale leziunilor traumatice la nivelul dinților temporari?","options":[{"id":"A","text":"Perioada critică de apariție este în jurul vârstei de 2-4 ani."},{"id":"B","text":"Raportul de incidență între băieți și fete este de 2:1."},{"id":"C","text":"Raportul de incidență între fete și băieți este de 2:1."},{"id":"D","text":"Violența domestică este singura cauză identificată sub vârsta de 5 ani."},{"id":"E","text":"Perioada critică de apariție este între 5-10 ani, când au loc accidentele de joacă."}],"correct":["A","B"],"pages":[427],"source":"set-2"},{"id":"set2-yLOOjH7r","fingerprint":"05c8f041b0632531","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce factori anatomici contribuie la predominanța luxațiilor față de fracturi la dinții temporari?","options":[{"id":"A","text":"Coroanele scurte și globuloase."},{"id":"B","text":"Structura laxă a osului maxilar."},{"id":"C","text":"Coroanele lungi și subțiri ale dinților temporari."},{"id":"D","text":"Prezența mugurilor dinților succesionali care ancorează ferm rădăcinile."},{"id":"E","text":"Rădăcinile aflate în curs de resorbție."}],"correct":["A","B","E"],"pages":[427],"source":"set-2"},{"id":"set2-cXdjcg8W","fingerprint":"ecebe7257f4a71a7","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este forma clinică specifică de traumatism pentru dinții temporari și care este localizarea cea mai frecventă a acestor leziuni?","options":[{"id":"A","text":"Subluxația; toți dinții de pe o hemiarcadă."},{"id":"B","text":"Fractura radiculară; molarii."},{"id":"C","text":"Fractura coronară necomplicată; incisivii inferiori."},{"id":"D","text":"Avulsia; caninii."},{"id":"E","text":"Luxația cu intruzie; incisivii centrali maxilari."}],"correct":["E"],"pages":[427],"source":"set-2"},{"id":"set2-5c3bZ3b7","fingerprint":"34c39c84bed92da4","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce măsuri terapeutice de urgență se impun în prima ședință în cazul unui traumatism dento-parodontal la un copil?","options":[{"id":"A","text":"Extracția dinților temporari foarte mobili."},{"id":"B","text":"Realizarea imediată a examenelor complementare pentru o evaluare completă."},{"id":"C","text":"Amânarea oricărui tratament până la dispariția edemelor, pentru o vizibilitate mai bună."},{"id":"D","text":"Toaleta sumară a plăgilor muco-gingivale."},{"id":"E","text":"Identificarea și îndepărtarea unor eventuali corpi străini."}],"correct":["A","D","E"],"pages":[427],"source":"set-2"},{"id":"set2-IYhRQL6v","fingerprint":"3c9f0041699371a0","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce consecințe potențiale pot avea traumatismele dento-parodontale ale dinților temporari?","options":[{"id":"A","text":"Pot perturba procesul de erupție pe arcada dentară a dinților succesionali."},{"id":"B","text":"Provoacă întotdeauna resorbția accelerată a rădăcinilor dinților temporari adiacenți."},{"id":"C","text":"Afectează exclusiv dinții temporari implicați, fără impact asupra dentiției permanente."},{"id":"D","text":"Pot afecta mugurii dinților succesionali."},{"id":"E","text":"Pot influența negativ structura și morfologia corono-radiculară a dinților permanenți."}],"correct":["A","D","E"],"pages":[427],"source":"set-2"},{"id":"set2-dpiUKuIS","fingerprint":"7408d83f5dd7a515","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele leziuni sunt clasificate ca traumatisme la nivelul țesuturilor de susținere?","options":[{"id":"A","text":"Avulsia."},{"id":"B","text":"Fracturi dento-alveolare."},{"id":"C","text":"Contuzia."},{"id":"D","text":"Fracturi coronare complicate."},{"id":"E","text":"Subluxația."}],"correct":["A","C","E"],"pages":[427],"source":"set-2"},{"id":"set2-1wXMtu0s","fingerprint":"ef04a59c31b45e50","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce include clasificarea traumatismelor la nivelul țesuturilor dure dentare?","options":[{"id":"A","text":"Fracturi radiculare."},{"id":"B","text":"Luxațiile."},{"id":"C","text":"Fracturi coronare necomplicate care implică doar smalțul sau smalțul și dentina."},{"id":"D","text":"Fracturi corono-radiculare."},{"id":"E","text":"Subluxația."}],"correct":["A","C","D"],"pages":[427],"source":"set-2"},{"id":"set2-ScUOzXOv","fingerprint":"438c8c8650396cfa","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce instrucțiuni primesc părinții unui copil care a suferit un traumatism dento-parodontal?","options":[{"id":"A","text":"Să administreze o dietă lichidă pentru o perioadă de 24 de ore."},{"id":"B","text":"Să revină la control după o lună, dacă nu apar complicații."},{"id":"C","text":"Să evite igienizarea zonei afectate pentru a permite vindecarea."},{"id":"D","text":"Să asigure copilului o alimentație moale, păstoasă timp de 1 săptămână."},{"id":"E","text":"Să asigure o igienă riguroasă a cavității orale."}],"correct":["D","E"],"pages":[427],"source":"set-2"},{"id":"set2-VzO-0gjp","fingerprint":"cb834b6b6ed59b34","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică corectă în cazul unei fracturi coronare la un dinte temporar, limitată strict la smalț?","options":[{"id":"A","text":"Netezirea marginilor anfractuoase, urmată de fluorizare și control la 3-4 săptămâni."},{"id":"B","text":"Restaurare finală cu capă și compozit."},{"id":"C","text":"Efectuarea unei pulpotomii vitale."},{"id":"D","text":"Sigilarea smalțului expus cu ciment ionomer de sticlă (CIS) fotopolimerizabil."},{"id":"E","text":"Extracția dintelui."}],"correct":["A"],"pages":[428],"source":"set-2"},{"id":"set2-6tn6oNkZ","fingerprint":"902fb09ca4998559","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele etape terapeutice sunt indicate în managementul unei fracturi coronare necomplicate la un dinte temporar, care implică atât smalțul, cât și dentina?","options":[{"id":"A","text":"Efectuarea unei pulpectomii devitale."},{"id":"B","text":"Dezinfectarea cu hipoclorit de sodiu."},{"id":"C","text":"Control clinic și radiologic după 3-4 săptămâni."},{"id":"D","text":"Sigilarea dentinei expuse cu ciment ionomer fotopolimerizabil."},{"id":"E","text":"Curățarea dentinei cu ser fiziologic."}],"correct":["B","D","E"],"pages":[428],"source":"set-2"},{"id":"set2-vyKjURfP","fingerprint":"a382db450df49e3a","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce atitudine terapeutică este recomandată pentru o fractură coronară complicată, recentă, la un dinte temporar aflat în stadiul 1 de dezvoltare?","options":[{"id":"A","text":"Control periodic la 2-3 săptămâni."},{"id":"B","text":"Extracție."},{"id":"C","text":"Pulpectomie devitală."},{"id":"D","text":"Sigilarea dentinei cu CIS fotopolimerizabil."},{"id":"E","text":"Pulpotomie vitală."}],"correct":["E"],"pages":[428],"source":"set-2"},{"id":"set2-geGxObUz","fingerprint":"dc8836780f5daa49","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"În cazul unei fracturi radiculare la un dinte temporar, în ce situație este indicată extracția?","options":[{"id":"A","text":"Când localizarea este în treimea medie."},{"id":"B","text":"Când fragmentul apical se resoarbe odată cu erupția dintelui permanent."},{"id":"C","text":"Când localizarea este în treimea cervicală."},{"id":"D","text":"Când localizarea este în treimea apicală și prognosticul este bun."},{"id":"E","text":"Când resorbția radiculară se desfășoară normal."}],"correct":["A","C"],"pages":[428],"source":"set-2"},{"id":"set2-wZW1KuWk","fingerprint":"f44248e5b67b90a7","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect fracturile corono-radiculare la dinții temporari?","options":[{"id":"A","text":"Dacă implicarea radiculară este redusă, se recomandă extracția dintelui."},{"id":"B","text":"În cazul prezentării tardive, se poate observa un polip ce separă fragmentele."},{"id":"C","text":"Sunt mai rar întâlnite la dinții temporari decât la cei permanenți."},{"id":"D","text":"Se extind sub marginea gingivală."},{"id":"E","text":"Sunt întotdeauna fracturi unice, cu o singură linie de fractură."}],"correct":["B","D"],"pages":[428],"source":"set-2"},{"id":"set2-Zho40rDL","fingerprint":"31548eb13d3dbc62","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Referitor la managementul unei fracturi radiculare localizate în treimea apicală a unui dinte temporar, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Prognosticul acestor fracturi este în general bun."},{"id":"B","text":"Controlul clinic se efectuează la 2-3 săptămâni."},{"id":"C","text":"Fragmentul apical radicular nu se resoarbe și interferează cu erupția dintelui permanent."},{"id":"D","text":"Fragmentul coronar se extrage imediat, indiferent de simptomatologie."},{"id":"E","text":"Controlul radiografic se face la 1 săptămână după traumatism."}],"correct":["A","B"],"pages":[428],"source":"set-2"},{"id":"set2-wm-2zEoY","fingerprint":"76c48f00d0c2fd8e","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce caracteristici sunt specifice fracturilor dento-alveolare?","options":[{"id":"A","text":"Sunt mai frecvente la maxilar."},{"id":"B","text":"Implică exclusiv țesuturile dure dentare, fără afectarea osului."},{"id":"C","text":"Implică și rebordul alveolar."},{"id":"D","text":"Sunt consecința unui traumatism de intensitate redusă."},{"id":"E","text":"Frontalii mandibulari se deplasează spre anterior împreună cu osul alveolar."}],"correct":["C","E"],"pages":[428],"source":"set-2"},{"id":"set2-yk4_dcEf","fingerprint":"20537bd7fb793569","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică corectă în cazul unei fracturi coronare complicate la un dinte temporar, în funcție de stadiul de dezvoltare?","options":[{"id":"A","text":"Condiția pentru pulpectomie în stadiul 2 este prezența a cel puțin jumătate din rădăcină."},{"id":"B","text":"În stadiul 3, se recomandă controlul periodic pentru monitorizare."},{"id":"C","text":"În stadiul 1, cu o fractură recentă, este indicată extracția."},{"id":"D","text":"În stadiul 2, cu un traumatism mai vechi, se recomandă pulpectomia devitală."},{"id":"E","text":"În stadiul 3, este indicată pulpotomia vitală."}],"correct":["D"],"pages":[428],"source":"set-2"},{"id":"set2-FROKfglp","fingerprint":"f8c435b65c675658","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care dintre următoarele caracteristici clinice este specifică contuziei unui dinte temporar?","options":[{"id":"A","text":"Necesitatea imobilizării cu șină de compozit timp de 4 săptămâni."},{"id":"B","text":"Sensibilitate la percuția în ax, fără mobilitate dentară."},{"id":"C","text":"Deplasarea dintelui în interiorul alveolei."},{"id":"D","text":"Sunet metalic la percuție."},{"id":"E","text":"Sângerare gingivală și mobilitate dentară fără deplasare."}],"correct":["B"],"pages":[429],"source":"set-2"},{"id":"set2-_W4NfKrd","fingerprint":"875313d7bf42f1d3","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce elemente definesc tabloul clinic și atitudinea terapeutică în subluxația unui dinte temporar?","options":[{"id":"A","text":"Ruperea extinsă a fibrelor ligamentare cu deplasarea dintelui."},{"id":"B","text":"Apariția imediată a unei sângerări gingivale."},{"id":"C","text":"Absența completă a mobilității dentare."},{"id":"D","text":"Prezența mobilității dentare, însă fără deplasare."},{"id":"E","text":"Recomandarea unui repaus alimentar timp de 1 săptămână."}],"correct":["B","D","E"],"pages":[429],"source":"set-2"},{"id":"set2-Ncp1vIrm","fingerprint":"bed05b32aa46e00c","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații referitoare la luxația cu intruzie a dinților temporari sunt adevărate?","options":[{"id":"A","text":"Este traumatismul care se soldează cel mai frecvent cu necroză și anchiloză dentară."},{"id":"B","text":"Dintele intrudat nu prezintă mobilitate clinică."},{"id":"C","text":"Examenul radiografic este o investigație opțională."},{"id":"D","text":"Tratamentul de elecție este întotdeauna extracția imediată a dintelui."},{"id":"E","text":"Este cea mai frecventă formă clinică de traumatism la dinții temporari."}],"correct":["A","B","E"],"pages":[429],"source":"set-2"},{"id":"set2-amfNV02o","fingerprint":"f41504360529432f","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"În ce situații este indicată extracția unui dinte temporar care a suferit o luxație cu intruzie?","options":[{"id":"A","text":"Imediat după traumatism, în toate cazurile, pentru a preveni anchiloza."},{"id":"B","text":"Atunci când coroana nu mai este vizibilă, iar radiografia sugerează un posibil contact cu mugurele dintelui permanent."},{"id":"C","text":"La apariția unor complicații de tip necrotic sau infecțios în timpul monitorizării."},{"id":"D","text":"Dacă dintele nu reerupe spontan după o perioadă de expectativă de 2-4 săptămâni."},{"id":"E","text":"Când coroana este parțial vizibilă, iar dintele apare scurtat pe radiografie."}],"correct":["B","C","D"],"pages":[429],"source":"set-2"},{"id":"set2-Z1T6wxoJ","fingerprint":"6e10bdf21f8a1247","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce rol joacă examenul radiografic în managementul luxației cu intruzie a unui dinte temporar?","options":[{"id":"A","text":"Un aspect scurtat al dintelui traumatizat pe radiografie indică o atitudine terapeutică de expectativă."},{"id":"B","text":"Este singurul examen care poate confirma prezența sângerării gingivale."},{"id":"C","text":"Confirmă mobilitatea dintelui, fiind un indicator pentru necesitatea imobilizării."},{"id":"D","text":"Un aspect elongat al dintelui intrudat pe radiografie sugerează riscul lezării mugurelui și indică extracția."},{"id":"E","text":"Este absolut necesar pentru a stabili raportul dintelui intrudat cu mugurele dintelui succesional."}],"correct":["A","D","E"],"pages":[429],"source":"set-2"},{"id":"set2-OjEMA-5v","fingerprint":"d11fec84a27e3d76","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt măsurile terapeutice corecte în cazul unui traumatism la dinții temporari ce implică și un fragment alveolar?","options":[{"id":"A","text":"Imobilizarea zonei afectate cu o șină de compozit pentru o perioadă de 4 săptămâni."},{"id":"B","text":"Monitorizare clinică fără nicio intervenție, așteptând vindecarea spontană."},{"id":"C","text":"Îndepărtarea dinților foarte mobili prin secționarea coroanei la nivelul rebordului alveolar."},{"id":"D","text":"Repoziționarea dinților și a fragmentului osos, urmată de sutură."},{"id":"E","text":"Controale periodice efectuate doar la 3 luni și la 1 an."}],"correct":["A","C","D"],"pages":[429],"source":"set-2"},{"id":"set2-YMr8_-LF","fingerprint":"508c649a9f934233","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt manifestările clinice caracteristice în luxația cu extruzie a unui dinte?","options":[{"id":"A","text":"Deplasarea dintelui din alveolă spre planul de ocluzie."},{"id":"B","text":"Absența completă a mobilității dentare."},{"id":"C","text":"Sensibilitate la percuție."},{"id":"D","text":"Prezența sângerării gingivale imediat după accident."},{"id":"E","text":"Sunet metalic la percuție."}],"correct":["A","C","D"],"pages":[430],"source":"set-2"},{"id":"set2-44cr6PcW","fingerprint":"c4a2a6957bf47ce3","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică indicată în cazul unui dinte temporar cu luxație cu extruzie care prezintă mobilitate accentuată?","options":[{"id":"A","text":"Repoziționare imediată și imobilizare timp de 7-14 zile."},{"id":"B","text":"Extracția dintelui."},{"id":"C","text":"Aplicarea unui menținător de spațiu fără a interveni asupra dintelui."},{"id":"D","text":"Repoziționare manuală sub anestezie topică, fără imobilizare."},{"id":"E","text":"Atitudine de expectativă, așteptând repoziționarea spontană."}],"correct":["B"],"pages":[430],"source":"set-2"},{"id":"set2-DKFrkuvS","fingerprint":"c54dc7339188dc39","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce trăsătură clinică specifică apare la percuție în cazul unei luxații vestibulare a unui dinte temporar?","options":[{"id":"A","text":"O senzație de mobilitate la percuție."},{"id":"B","text":"Un sunet mat."},{"id":"C","text":"Sensibilitate crescută, fără un sunet specific."},{"id":"D","text":"Absența oricărui sunet."},{"id":"E","text":"Un sunet metalic."}],"correct":["E"],"pages":[430],"source":"set-2"},{"id":"set2-UEj_uvhF","fingerprint":"fac8de8e9ed5617e","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"În contextul unei luxații vestibulare a unui dinte temporar, care este conduita terapeutică dacă evaluarea radiografică arată că mugurele dintelui succesional nu este afectat?","options":[{"id":"A","text":"Repoziționare manuală imediată sub anestezie loco-regională."},{"id":"B","text":"Sutură gingivală pentru a stabiliza țesuturile moi."},{"id":"C","text":"Atitudine de expectativă, permițând repoziționarea treptată sub acțiunea forței musculare."},{"id":"D","text":"Imobilizarea dintelui pentru o perioadă de 2-3 săptămâni."},{"id":"E","text":"Extracția imediată a dintelui temporar pentru a preveni complicațiile."}],"correct":["C"],"pages":[430],"source":"set-2"},{"id":"set2-ixlVsQTc","fingerprint":"2d44e87be7a650ed","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect particularitățile luxației orale a unui dinte temporar superior?","options":[{"id":"A","text":"Tratamentul de elecție este expectativ, similar luxației vestibulare."},{"id":"B","text":"Se caracterizează printr-o mobilitate dentară accentuată."},{"id":"C","text":"Coroana este deplasată spre vestibul, iar rădăcina spre palatinal."},{"id":"D","text":"Repoziționarea manuală se poate efectua sub anestezie topică."},{"id":"E","text":"Poate determina apariția unui angrenaj invers."}],"correct":["D","E"],"pages":[430],"source":"set-2"},{"id":"set2-FDlUE5gW","fingerprint":"bb80d1237265da0b","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce include protocolul de urmărire pe termen lung pentru un pacient cu luxație laterală?","options":[{"id":"A","text":"Un control radiologic la 6-8 săptămâni."},{"id":"B","text":"Un control clinic la 2-3 săptămâni."},{"id":"C","text":"Un control radiologic la 1 an."},{"id":"D","text":"Controale clinice săptămânale timp de o lună."},{"id":"E","text":"Un control radiologic la 1 lună."}],"correct":["A","B","C"],"pages":[430],"source":"set-2"},{"id":"set2-E82Iul60","fingerprint":"2391e45b20bda752","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care este atitudinea terapeutică recomandată în cazul avulsiei traumatice a unui dinte temporar și care este raționamentul acesteia?","options":[{"id":"A","text":"Reimplantarea nu se recomandă din cauza riscului de lezare a mugurelui dintelui succesional."},{"id":"B","text":"Așteptarea erupției dintelui permanent fără nicio intervenție."},{"id":"C","text":"Aplicarea unui menținător de spațiu pentru a restaura estetica și funcționalitatea."},{"id":"D","text":"Reimplantarea dintelui, deoarece menține integritatea arcadei dentare."},{"id":"E","text":"Realizarea unei radiografii toracice pentru a confirma diagnosticul de avulsie."}],"correct":["A","C"],"pages":[430],"source":"set-2"},{"id":"set2-Ks97nww0","fingerprint":"aa8e36dfcf08452b","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații referitoare la modificările de culoare ale coroanei dinților temporari consecutiv unui traumatism sunt adevărate?","options":[{"id":"A","text":"Hemoragia pulpară determină o colorație a coroanei la 1-2 zile de la traumatism."},{"id":"B","text":"Apariția unui aspect gri-cenușiu al coroanei la 3-4 săptămâni de la traumatism este sugestivă pentru necroza pulpară."},{"id":"C","text":"Necroza pulpară se manifestă printr-un aspect gălbui al coroanei."},{"id":"D","text":"Metamorfoza calcică duce la apariția unui aspect gălbui al coroanei, fără a afecta rizaliza."},{"id":"E","text":"Metamorfoza calcică este asociată cu un aspect gri-cenușiu al coroanei."}],"correct":["A","B","D"],"pages":[431],"source":"set-2"},{"id":"set2-nki17i0H","fingerprint":"3daa79dc921d5176","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce complicație a traumatismelor dinților temporari este definită ca o fuziune între rădăcină și os, conducând la infrapoziție?","options":[{"id":"A","text":"Anchiloza dentară"},{"id":"B","text":"Metamorfoza calcică"},{"id":"C","text":"Resorbția inflamatorie internă"},{"id":"D","text":"Hemoragia pulpară"},{"id":"E","text":"Hiperemia pulpară"}],"correct":["A"],"pages":[431],"source":"set-2"},{"id":"set2-zL0au1Pq","fingerprint":"e93039b66dd13d3f","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Afectarea mugurelui dintelui succesional este o complicație a traumatismelor dinților temporari. Care dintre următoarele manifestări sunt asociate cu această complicație?","options":[{"id":"A","text":"Oprirea în evoluție a mugurelui dentar."},{"id":"B","text":"Apariția dilacerațiilor."},{"id":"C","text":"Apariția hipoplaziilor de smalț."},{"id":"D","text":"Formarea de dinți supranumerari."},{"id":"E","text":"Accelerarea erupției dintelui succesional."}],"correct":["A","B","C"],"pages":[431],"source":"set-2"},{"id":"set2-6I9U2BbD","fingerprint":"9f9fff5961869402","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele caracteristici epidemiologice sunt asociate cu traumatismele dento-parodontale ale dinților permanenți la copii?","options":[{"id":"A","text":"Frecvența maximă de apariție este în intervalul de vârstă 8-10 ani."},{"id":"B","text":"Mediul rural este semnificativ mai afectat decât mediul urban."},{"id":"C","text":"Raportul de afectare între sexul masculin și cel feminin este de 2:1."},{"id":"D","text":"Sexul feminin este de 2 ori mai afectat comparativ cu sexul masculin."},{"id":"E","text":"Aproximativ 35% dintre copii suferă un traumatism în timpul vieții."}],"correct":["A","C","E"],"pages":[431],"source":"set-2"},{"id":"set2-Hq2zLkL2","fingerprint":"e022c89e7b3aedec","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce factori predispozanți sunt corelați cu posibilitatea apariției leziunilor traumatice la dinții permanenți?","options":[{"id":"A","text":"Prezența unor procese carioase profunde."},{"id":"B","text":"Microdonția."},{"id":"C","text":"Anomalia dento-maxilară de tip Clasa a II-a/1 Angle."},{"id":"D","text":"Tulburări de mineralizare."},{"id":"E","text":"Bruxismul."}],"correct":["A","C","D"],"pages":[431],"source":"set-2"},{"id":"set2-1LByvmiX","fingerprint":"316cf9d7c96f7d9d","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este cea mai prevalentă formă clinică de traumatism la dinții permanenți și care este explicația principală pentru aceasta?","options":[{"id":"A","text":"Fracturile corono-radiculare, din cauza raportului coroană-rădăcină scăzut și a osului mai dens."},{"id":"B","text":"Fisurile de smalț, din cauza proceselor carioase profunde."},{"id":"C","text":"Fracturile radiculare, din cauza unui țesut osos mai dens."},{"id":"D","text":"Luxațiile, din cauza unui raport coroană-rădăcină crescut."},{"id":"E","text":"Avulsia, din cauza prezenței anomaliilor dento-maxilare."}],"correct":["A"],"pages":[431],"source":"set-2"},{"id":"set2-bwiQuXE0","fingerprint":"7cb23746384e4315","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele cauze sunt incriminate frecvent în etiologia traumatismelor dento-parodontale la dinții permanenți?","options":[{"id":"A","text":"Erupția precoce a dinților permanenți."},{"id":"B","text":"Consumul excesiv de alimente dure."},{"id":"C","text":"Manevre terapeutice iatrogene."},{"id":"D","text":"Loviturile directe la nivelul feței, cum ar fi cele cu pumnul sau obiecte contondente."},{"id":"E","text":"Accidentele de joacă sau în timpul orelor de sport."}],"correct":["C","D","E"],"pages":[431],"source":"set-2"},{"id":"set2-Zyru-GtS","fingerprint":"b01ed3bada6beb0c","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele leziuni sunt clasificate ca traumatisme la nivelul țesuturilor dure dentare ale dinților permanenți?","options":[{"id":"A","text":"Fracturile coronare complicate cu deschiderea camerei pulpare."},{"id":"B","text":"Avulsia."},{"id":"C","text":"Fracturile corono-radiculare."},{"id":"D","text":"Subluxația."},{"id":"E","text":"Fisura de smalț."}],"correct":["A","C","E"],"pages":[431],"source":"set-2"},{"id":"set2-04MJTJd_","fingerprint":"9b46ee93762f730f","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele elemente sunt evaluate în cadrul examenului exo-bucal al unui pacient cu traumatism dento-alveolar?","options":[{"id":"A","text":"Prezența rigidității sau durerii în zona cervicală."},{"id":"B","text":"Gradul și tipul mobilității dentare."},{"id":"C","text":"Modificările de ocluzie."},{"id":"D","text":"Dinamica mandibulară și prezența cracmentelor la nivelul articulației temporo-mandibulare."},{"id":"E","text":"Inspecția și palparea țesuturilor moi pentru a decela plăgi sau hematoame."}],"correct":["A","D","E"],"pages":[432],"source":"set-2"},{"id":"set2-hYBGSVVh","fingerprint":"4d5fda14f962454c","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce indică o percuție pozitivă la un dinte care a suferit un traumatism?","options":[{"id":"A","text":"O fisură coronară."},{"id":"B","text":"Instalarea inflamației la nivelul ligamentului parodontal."},{"id":"C","text":"Un șoc traumatic tranzitoriu al pulpei."},{"id":"D","text":"Necroza pulpară confirmată."},{"id":"E","text":"O fractură radiculară longitudinală."}],"correct":["B"],"pages":[432],"source":"set-2"},{"id":"set2-hIXfdReM","fingerprint":"d2fb6071d3ddea2a","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Referitor la testele de vitalitate efectuate pe dinții traumatizați la copii, care afirmație este corectă?","options":[{"id":"A","text":"Testul electric este contraindicat la dinții imaturi."},{"id":"B","text":"Testul termic la rece poate oferi informații utile chiar și la dinții imaturi."},{"id":"C","text":"Testul termic la cald este metoda de elecție."},{"id":"D","text":"Răspunsurile fals negative la testul la rece sunt foarte rare la dinții traumatizați."},{"id":"E","text":"Lipsa răspunsului la un test de vitalitate confirmă imediat diagnosticul de necroză pulpară."}],"correct":["B"],"pages":[432],"source":"set-2"},{"id":"set2-48fN7K8K","fingerprint":"e339b8595407cbf4","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele informații pot fi evidențiate printr-un examen radiologic în contextul unui traumatism dentar?","options":[{"id":"A","text":"Aspectul zonei periapicale."},{"id":"B","text":"Prezența fracturilor osoase."},{"id":"C","text":"Prezența fisurilor dentare coronare."},{"id":"D","text":"Traiectul unei fracturi radiculare."},{"id":"E","text":"Gradul de dezvoltare radiculară."}],"correct":["A","B","D","E"],"pages":[432],"source":"set-2"},{"id":"set2-YVgQvcd6","fingerprint":"034d27657c797a61","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce tip de examen radiologic este indicat în mod specific la un pacient inconștient care prezintă dinți avulsionați?","options":[{"id":"A","text":"Ortopantomografie."},{"id":"B","text":"Radiografii ocluzale."},{"id":"C","text":"Radiografii de torace sau abdomen."},{"id":"D","text":"Tomografie computerizată cu fascicul conic (CBCT)."},{"id":"E","text":"Radiografii retro-alveolare în incidențe speciale."}],"correct":["C"],"pages":[432],"source":"set-2"},{"id":"set2-uXVY2nYc","fingerprint":"9faf7670f8ed2823","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"În ce situație se recomandă efectuarea unui examen neurologic complementar la un pacient cu traumatism dentar?","options":[{"id":"A","text":"În cazul prezenței unei fracturi a rebordului alveolar."},{"id":"B","text":"Când se observă o limitare a deschiderii cavității bucale."},{"id":"C","text":"În toate cazurile de avulsie dentară."},{"id":"D","text":"Când pacientul prezintă cefalee, amețeală și vomă."},{"id":"E","text":"La apariția epistaxisului sau vertijului."}],"correct":["D"],"pages":[432],"source":"set-2"},{"id":"set2-wP49pdSI","fingerprint":"92873dcac3f15553","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este scopul și metoda corectă de utilizare a transiluminării în examinarea unui dinte traumatizat?","options":[{"id":"A","text":"Detectează deplasările dentare patologice prin iluminarea spațiului periodontal."},{"id":"B","text":"Evidențiază fracturile radiculare prin aplicarea luminii dinspre vestibular."},{"id":"C","text":"Identifică prezența resorbției radiculare interne."},{"id":"D","text":"Evaluează vitalitatea pulpară prin observarea modificării culorii dintelui."},{"id":"E","text":"Permite depistarea fisurilor dentare prin aplicarea spotului lămpii cu lumină ultravioletă pe suprafața dentară dinspre oral."}],"correct":["E"],"pages":[432],"source":"set-2"},{"id":"set2-CSkVKJrE","fingerprint":"1da7b6339c8eb6c2","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt asocierile corecte între semnele clinice observate după un traumatism facial și posibilele fracturi subiacente?","options":[{"id":"A","text":"Sângerarea din meatul auditiv extern poate fi asociată cu o fractură zigomatică."},{"id":"B","text":"Hematomul sublingual poate indica o fractură mandibulară la nivelul simfizei mentoniere sau în regiunea canină."},{"id":"C","text":"Echimoza din zona suborbitară asociată cu hemoragie conjunctivală indică o fractură condiliană."},{"id":"D","text":"Echimoza din spatele urechii, în regiunea mastoidă, poate indica o fractură de bază de craniu."},{"id":"E","text":"Echimoza de la nivelul bărbiei poate indica o fractură mandibulară."}],"correct":["B","D","E"],"pages":[433],"source":"set-2"},{"id":"set2-8mkw_XjZ","fingerprint":"6644408d62fea57c","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce caracteristici sunt specifice fisurii de smalț?","options":[{"id":"A","text":"Simptomatologia include întotdeauna durere spontană și intensă."},{"id":"B","text":"Diagnosticul se stabilește prin transiluminare."},{"id":"C","text":"Se caracterizează prin pierdere de substanță dentară vizibilă clinic."},{"id":"D","text":"Este un traumatism minor care depășește joncțiunea smalț-dentină."},{"id":"E","text":"Tratamentul de protecție constă în aplicarea a două straturi de bonding fotopolimerizabil."}],"correct":["B","E"],"pages":[433],"source":"set-2"},{"id":"set2-UI-lI1pI","fingerprint":"3a7c1ebc31ad607e","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică în cazul unei fracturi coronare necomplicate limitate doar la nivelul smalțului?","options":[{"id":"A","text":"Netezirea marginilor zonei de fractură, fluorizare și control periodic al vitalității."},{"id":"B","text":"Realizarea unei restaurări provizorii cu ionomer de sticlă."},{"id":"C","text":"Efectuarea imediată a unui tratament endodontic."},{"id":"D","text":"Aplicarea a două straturi de bonding fotopolimerizabil."},{"id":"E","text":"Aplicarea unui coafaj indirect cu hidroxid de calciu."}],"correct":["A"],"pages":[433],"source":"set-2"},{"id":"set2-PX9bC_DE","fingerprint":"eca4471bca373fdf","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este obiectivul terapeutic principal în cazul unei fracturi coronare necomplicate cu afectarea smalțului și dentinei la un dinte permanent tânăr?","options":[{"id":"A","text":"Efectuarea unui coafaj direct pentru a stimula formarea de dentină de reparație."},{"id":"B","text":"Netezirea marginilor ascuțite pentru a preveni lezarea mucoasei orale."},{"id":"C","text":"Monitorizarea dintelui timp de 3 luni înainte de a interveni, pentru a evalua răspunsul pulpar."},{"id":"D","text":"Prevenirea infiltrației bacteriene printr-o restaurare de compozit, fără altă intervenție."},{"id":"E","text":"Protecția dentinei prin sigilarea canaliculelor dentinare expuse pentru a asigura păstrarea vitalității pulpare și continuarea apexogenezei."}],"correct":["E"],"pages":[433],"source":"set-2"},{"id":"set2-tbpa2M3F","fingerprint":"eb59eecf1a68564c","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce factori influențează decizia terapeutică în cazul fracturilor coronare complicate cu deschiderea camerei pulpare la dinții permanenți tineri?","options":[{"id":"A","text":"Timpul scurs de la traumatism."},{"id":"B","text":"Prezența sau absența sensibilității la rece."},{"id":"C","text":"Tipul agentului traumatic (cădere, lovitură directă etc.)."},{"id":"D","text":"Gradul dezvoltării radiculare."},{"id":"E","text":"Mărimea expunerii pulpare."}],"correct":["A","D","E"],"pages":[433],"source":"set-2"},{"id":"set2-P28ehqTo","fingerprint":"508d2bf557d2884c","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Un pacient tânăr se prezintă la 4 ore după un traumatism la un dinte permanent imatur, prezentând o expunere pulpară de 0.8 mm. Care este tehnica de tratament recomandată în această situație?","options":[{"id":"A","text":"Depulparea și obturația de canal"},{"id":"B","text":"Extracția dintelui"},{"id":"C","text":"Coafaj direct"},{"id":"D","text":"Pulpotomia vitală parțială (Cvek)"},{"id":"E","text":"Pulpotomia vitală totală"}],"correct":["C"],"pages":[434],"source":"set-2"},{"id":"set2-VoKa3r3i","fingerprint":"b2916c70dbe25f46","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect procedura de pulpotomie vitală parțială (Cvek) la dinții imaturi?","options":[{"id":"A","text":"Imobilizarea rigidă a dintelui timp de 4 luni este obligatorie."},{"id":"B","text":"Controlul clinic și radiografic se efectuează obligatoriu la 6-8 săptămâni post-intervenție."},{"id":"C","text":"Se aplică o pastă pe bază de hidroxid de calciu sau MTA în contact direct cu țesutul pulpar."},{"id":"D","text":"Se realizează o obturație de bază cu ionomer de sticlă."},{"id":"E","text":"Presupune îndepărtarea țesutului pulpar expus și contaminat."}],"correct":["B","C","D","E"],"pages":[434],"source":"set-2"},{"id":"set2-0h6WpuW0","fingerprint":"896d733cc53e07c3","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt caracteristicile generale ale fracturilor radiculare?","options":[{"id":"A","text":"Sunt traumatisme care uneori pot fi suspectate doar pe baza pierderii vitalității dentare."},{"id":"B","text":"Implică smalțul, dentina și cementul."},{"id":"C","text":"Localizarea cea mai frecventă este în treimea apicală."},{"id":"D","text":"Diagnosticul se bazează întotdeauna pe prezența mobilității anormale a coroanei."},{"id":"E","text":"Apar mai frecvent la copiii mai mari, după terminarea dezvoltării radiculare."}],"correct":["A","E"],"pages":[434],"source":"set-2"},{"id":"set2-A_9Yk-Ha","fingerprint":"b69056493352c386","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Cum se stabilește diagnosticul unei fracturi radiculare localizate în treimea cervicală sau medie?","options":[{"id":"A","text":"Prin absența totală a mobilității sau deplasării fragmentului coronar."},{"id":"B","text":"Prin apariția unei mobilități anormale a coroanei, cu sau fără deplasarea fragmentului coronar."},{"id":"C","text":"Prin vizualizarea directă a liniei de fractură la nivelul joncțiunii smalț-cement."},{"id":"D","text":"Exclusiv prin depistarea unei linii radiotransparente la nivel apical."},{"id":"E","text":"Doar pe baza pierderii vitalității dentare, fără alte semne clinice."}],"correct":["B"],"pages":[434],"source":"set-2"},{"id":"set2-twFFVA38","fingerprint":"d40ca38fe0c0b5a4","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este conduita terapeutică indicată în cazul unei fracturi radiculare la un dinte permanent, cu deplasarea fragmentului coronar?","options":[{"id":"A","text":"Aplicarea periodică de hidroxid de calciu la fiecare 3 luni fără repoziționare prealabilă."},{"id":"B","text":"Monitorizarea periodică fără nicio intervenție de imobilizare."},{"id":"C","text":"Imobilizare funcțională (semi-rigidă) timp de 4 săptămâni."},{"id":"D","text":"Repoziționare imediată în anestezie și imobilizare rigidă timp de 4 luni."},{"id":"E","text":"Depulparea imediată a fragmentului coronar și aplicarea unei paste cu antibiotic."}],"correct":["D"],"pages":[434],"source":"set-2"},{"id":"set2-UV0Ei5-B","fingerprint":"914e33522a486e94","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următorii factori sunt asociați cu un prognostic nefavorabil în cazul fracturilor radiculare?","options":[{"id":"A","text":"Deplasarea fragmentului coronar este absentă sau sub 1mm."},{"id":"B","text":"Fragmentul coronar prezintă o deplasare accentuată."},{"id":"C","text":"Dintele răspunde pozitiv la testele de vitalitate."},{"id":"D","text":"Apexul dintelui este închis."},{"id":"E","text":"Localizarea fracturii în treimea apicală sau medie."}],"correct":["B","D"],"pages":[434],"source":"set-2"},{"id":"set2-GLMjP0UV","fingerprint":"0fefec3c8fd3d054","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce structuri dentare sunt afectate simultan într-o fractură corono-radiculară?","options":[{"id":"A","text":"Doar cementul și țesutul pulpar"},{"id":"B","text":"Smalț și dentină"},{"id":"C","text":"Dentină și cement"},{"id":"D","text":"Doar smalțul și țesutul pulpar"},{"id":"E","text":"Smalț, dentină și cement"}],"correct":["E"],"pages":[434],"source":"set-2"},{"id":"set2-PPqmOcay","fingerprint":"078490a710c7cbc1","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică corectă în cazul unei fracturi corono-radiculare la un dinte matur, cu linia de fractură extinsă sub creasta alveolară?","options":[{"id":"A","text":"Îndepărtarea fragmentului coronar, urmată de tratament endodontic complet și restaurare coronară complexă."},{"id":"B","text":"Sigilarea dentinei cu ciment ionomer de sticlă, urmată de restaurare cu compozit."},{"id":"C","text":"Efectuarea unei pulpectomii parțiale pentru menținerea vitalității pulpei radiculare."},{"id":"D","text":"Efectuarea apexificării pentru a asigura sigilarea apicală."},{"id":"E","text":"Efectuarea unei pulpotomii parțiale Cvek, urmată de restaurare cu compozit."}],"correct":["A"],"pages":[435],"source":"set-2"},{"id":"set2-K-RUPTST","fingerprint":"4392e89b918e5ef6","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele semne clinice și măsuri terapeutice sunt caracteristice subluxației dinților permanenți?","options":[{"id":"A","text":"Sângerare la nivelul șanțului gingival."},{"id":"B","text":"Absența completă a mobilității dentare."},{"id":"C","text":"Deplasarea coroanei dentare spre vestibular sau oral."},{"id":"D","text":"Imobilizare pentru maxim 14 zile în caz de mobilitate accentuată."},{"id":"E","text":"Mobilitate dentară fără deplasare."}],"correct":["A","D","E"],"pages":[435],"source":"set-2"},{"id":"set2-k7Ws7imy","fingerprint":"91ae39e63911c603","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este elementul clinic fundamental ce diferențiază contuzia de subluxație în traumatismele țesuturilor de susținere?","options":[{"id":"A","text":"Prezența mobilității dentare."},{"id":"B","text":"Prezența sensibilității la percuție."},{"id":"C","text":"Necesitatea unei alimentații moi timp de 2 săptămâni."},{"id":"D","text":"Prezența deplasării dentare."},{"id":"E","text":"Producerea unei leziuni la nivelul ligamentului de susținere."}],"correct":["A"],"pages":[435],"source":"set-2"},{"id":"set2-zr7blONE","fingerprint":"af4988c7d7b8cfcb","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații despre luxație sunt adevărate?","options":[{"id":"A","text":"Luxația laterală se poate asocia cu o fractură alveolară."},{"id":"B","text":"Reprezintă un traumatism ce determină deplasarea dintelui."},{"id":"C","text":"Este un traumatism caracterizat prin mobilitate fără deplasare."},{"id":"D","text":"Poate duce frecvent la pierderea vitalității pulpare."},{"id":"E","text":"Apare mai frecvent la dinții maturi datorită stabilității ligamentare."}],"correct":["A","B","D"],"pages":[435],"source":"set-2"},{"id":"set2-GoMMUKUw","fingerprint":"ec5f1046ece3abd8","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"În cazul unei fracturi corono-radiculare la un dinte imatur vital, care este abordarea terapeutică descrisă?","options":[{"id":"A","text":"Apexificarea pentru a asigura sigilarea apicală."},{"id":"B","text":"Sigilarea dentinei cu ciment ionomer de sticlă."},{"id":"C","text":"Efectuarea unei pulpectomii parțiale."},{"id":"D","text":"Pulpotomie parțială Cvek."},{"id":"E","text":"Tratament endodontic complet urmat de restaurare complexă."}],"correct":["C"],"pages":[435],"source":"set-2"},{"id":"set2-Hk_ajh-t","fingerprint":"d2c4eaa27ee42575","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Un pacient prezintă coroana unui dinte permanent tânăr deplasată spre oral, fără a avea mobilitate dentară. Care este atitudinea terapeutică de urgență indicată?","options":[{"id":"A","text":"Imobilizarea dintelui timp de 14 zile."},{"id":"B","text":"Monitorizare clinică și radiologică la 1, 3, 6 și 12 luni."},{"id":"C","text":"Scoaterea dintelui din ocluzie și repaus masticator."},{"id":"D","text":"Repoziționarea manuală imediată."},{"id":"E","text":"Efectuarea unei pulpotomii parțiale Cvek."}],"correct":["D"],"pages":[435],"source":"set-2"},{"id":"set2-MCh2PnKa","fingerprint":"ce657629f769da86","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt afirmațiile corecte referitoare la managementul luxației laterale?","options":[{"id":"A","text":"La dinții imaturi este întotdeauna necesară depulparea profilactică."},{"id":"B","text":"În cazul asocierii cu o fractură alveolară severă, imobilizarea poate dura până la 8 săptămâni."},{"id":"C","text":"Monitorizarea clinică și radiologică a dinților imaturi se face la 1, 3, 6 și 12 luni post-traumatism."},{"id":"D","text":"Repoziționarea manuală se efectuează de rutină fără anestezie."},{"id":"E","text":"Imobilizarea funcțională standard durează 2 săptămâni."}],"correct":["B","C"],"pages":[436],"source":"set-2"},{"id":"set2-lNgS-1tL","fingerprint":"8936681e186da259","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt condițiile pe care trebuie să le îndeplinească un sistem de imobilizare utilizat în luxația laterală?","options":[{"id":"A","text":"Să fie rapid și ușor de realizat."},{"id":"B","text":"Să nu producă disfuncții ocluzale."},{"id":"C","text":"Să respecte parodonțiul marginal."},{"id":"D","text":"Să se extindă pe un singur dinte de fiecare parte a zonei traumatizate."},{"id":"E","text":"Să fie rigid pentru a preveni orice micromișcare."}],"correct":["A","B","C"],"pages":[436],"source":"set-2"},{"id":"set2-iWU6zvnZ","fingerprint":"626163198ec27580","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce caracteristici clinice și radiografice sunt specifice luxației cu extruzie în cazul dinților permanenți tineri?","options":[{"id":"A","text":"Dispariția totală a coroanei de pe arcadă."},{"id":"B","text":"Examenul radiografic arată lărgirea spațiului periodontal."},{"id":"C","text":"Apariția la percuție a unui sunet metalic."},{"id":"D","text":"Deplasarea în axul vertical al dintelui și mobilitate dentară."},{"id":"E","text":"Coroana este deplasată spre vestibular, fără mobilitate dentară."}],"correct":["B","D"],"pages":[436],"source":"set-2"},{"id":"set2-XM1h4-BX","fingerprint":"1cc73fec32917088","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică corectă în cazul unei luxații cu extruzie în cazul dinților permanenți tineri?","options":[{"id":"A","text":"Extracția imediată a dintelui."},{"id":"B","text":"Imobilizare pe o perioadă de 3-4 săptămâni."},{"id":"C","text":"Extruzie ortodontică pentru finalizarea repoziționării."},{"id":"D","text":"Repoziționare manuală imediată urmată de imobilizare timp de 2 săptămâni."},{"id":"E","text":"Așteptarea repoziționării spontane, în special la dinții imaturi."}],"correct":["D"],"pages":[436],"source":"set-2"},{"id":"set2-LBj2Fadz","fingerprint":"e7db5016acefbe2b","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce elemente definesc luxația cu intruzie și prognosticul său?","options":[{"id":"A","text":"Principala complicație este lărgirea spațiului periodontal."},{"id":"B","text":"Este considerat un traumatism minor, cu prognostic favorabil."},{"id":"C","text":"Prognosticul nefavorabil este asociat cu compresia pachetului vasculo-nervos."},{"id":"D","text":"Clinic, se poate manifesta prin apariția unui sunet metalic la percuție."},{"id":"E","text":"Ruperea fibrelor ligamentare este parțială, permițând re-erupția rapidă."}],"correct":["C","D"],"pages":[436],"source":"set-2"},{"id":"set2-tsfqaBfs","fingerprint":"5505da2e891c2462","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care este abordarea terapeutică în luxația cu intruzie a unui dinte permanent tânăr, în funcție de stadiul dezvoltării radiculare?","options":[{"id":"A","text":"Depulparea este necesară în toate cazurile, indiferent de stadiul radicular."},{"id":"B","text":"Dacă un dinte cu rădăcină incompletă nu reerupe, se indică extracția."},{"id":"C","text":"La dinții cu rădăcină complet formată se așteaptă re-erupția spontană."},{"id":"D","text":"Extruzia ortodontică imediată este recomandată pentru dinții cu rădăcină complet formată."},{"id":"E","text":"La dinții cu rădăcină incomplet formată, parțial intrudați, se așteaptă reerupția timp de 2-3 săptămâni."}],"correct":["D","E"],"pages":[436],"source":"set-2"},{"id":"set2-CgGciLrI","fingerprint":"8a2e4a9c237a5a05","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Un copil suferă o avulsie dentară. Care sunt recomandările corecte de prim ajutor ce trebuie oferite aparținătorilor?","options":[{"id":"A","text":"Se manevrează dintele de rădăcină pentru o priză mai bună."},{"id":"B","text":"Examenul radiologic este obligatoriu pentru a exclude o intruzie totală."},{"id":"C","text":"Prognosticul este bun dacă replantarea se face în primele 30 de minute."},{"id":"D","text":"Dintele se spală cu lapte sau soluție salină și se replantează imediat în alveolă, dacă este posibil."},{"id":"E","text":"Dacă replantarea nu este posibilă, dintele se păstrează uscat, într-o batistă curată."}],"correct":["D"],"pages":[436],"source":"set-2"},{"id":"set2-hQD49K1a","fingerprint":"c5b9c55d9c8b26c9","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică recomandată în cazul replantării unui dinte permanent tânăr la un pacient care se prezintă la 40 de minute după traumatism?","options":[{"id":"A","text":"Dintele se menține într-o soluție antiseptică cu antibiotice timp de 20 de minute."},{"id":"B","text":"Dintele se spală și se manevrează doar de coroană pentru a conserva fibrele ligamentare."},{"id":"C","text":"Depulparea dintelui se efectuează imediat, înainte de inserarea acestuia în alveolă."},{"id":"D","text":"Alveola se pregătește prin chiuretaj viguros pentru a stimula sângerarea și formarea unui nou cheag."},{"id":"E","text":"Se face imobilizare timp de 3 luni pentru a asigura o vindecare osoasă completă."}],"correct":["B"],"pages":[437],"source":"set-2"},{"id":"set2-Oyu0pEqj","fingerprint":"4ce66cea8dc50f06","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce măsuri specifice sunt indicate în managementul replantării unui dinte permanent avulsionat dacă prezentarea la medic se face tardiv, după 60 de minute de la traumatism?","options":[{"id":"A","text":"Dintele se spală și se menține într-o soluție antiseptică sau cu antibiotice timp de 20 de minute."},{"id":"B","text":"În cazul dinților foarte imaturi, depulparea se efectuează obligatoriu la o săptămână după imobilizare pentru a preveni necroza."},{"id":"C","text":"Îndepărtarea porțiunilor necrozate din ligament se realizează cu ajutorul unui tifon umezit în soluție salină."},{"id":"D","text":"La o săptămână după imobilizare se recomandă efectuarea depulpării, urmată de aplicarea unui preparat cu antibiotic și corticosteroid."},{"id":"E","text":"Imobilizarea dintelui se face pentru o perioadă de o lună pentru a compensa perioada extra-alveolară prelungită."}],"correct":["A","C","D"],"pages":[437],"source":"set-2"},{"id":"set2-oyKyNrGR","fingerprint":"7ec231c203ebbb76","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care dintre următoarele complicații post-traumatice la dinții permanenți este un proces degenerativ ce duce la obliterarea canalului radicular și se manifestă clinic prin colorația galben-opacă a coroanei?","options":[{"id":"A","text":"Hemoragia internă"},{"id":"B","text":"Resorbția radiculară externă"},{"id":"C","text":"Resorbția radiculară internă"},{"id":"D","text":"Calcifierea țesutului pulpar"},{"id":"E","text":"Anchiloza dentară"}],"correct":["D"],"pages":[437],"source":"set-2"},{"id":"set2-HwhobevV","fingerprint":"5d836fc3b0e63879","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Selectați afirmațiile corecte referitoare la complicațiile traumatismelor la dinții permanenți.","options":[{"id":"A","text":"Resorbția radiculară internă apare frecvent după luxații și poate evolua până la perforația rădăcinii."},{"id":"B","text":"Anchiloza dentară apare ca urmare a distrugerii extinse a ligamentului parodontal și este semnalată clinic prin infrapoziția dintelui."},{"id":"C","text":"Resorbția radiculară externă este un proces degenerativ ce duce la obliterarea canalului radicular."},{"id":"D","text":"Calcifierea țesutului pulpar se manifestă clinic prin infrapoziția dintelui traumatizat."},{"id":"E","text":"Hemoragia internă, manifestată la 1-2 zile post-traumatic, este un proces reversibil și nu necesită terapie pulpară."}],"correct":["A","B","E"],"pages":[437],"source":"set-2"},{"id":"set2-tuVGnfTM","fingerprint":"6205110cb606697d","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"În care dintre următoarele situații replantarea fără depulpare a unui dinte permanent tânăr avulsionat are cel mai favorabil prognostic?","options":[{"id":"A","text":"Când apexul dintelui este foarte imatur și replantarea se realizează în maxim 30 de minute de la traumatism."},{"id":"B","text":"Când replantarea se face după 60 de minute, dar dintele a fost conservat în soluție salină."},{"id":"C","text":"Când apexul dintelui este complet edificat, asigurând o stabilitate mai bună în alveolă."},{"id":"D","text":"Când dintele este replantat în primele 60 de minute, indiferent de stadiul de dezvoltare al apexului."},{"id":"E","text":"Când se realizează o imobilizare rigidă pentru o perioadă de 30 de zile."}],"correct":["A"],"pages":[437],"source":"set-2"},{"id":"set2-T3-Q7ttq","fingerprint":"f622b0c998c316bc","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt afirmațiile corecte referitoare la atitudinea terapeutică în cazul unui pacient care a suferit o sincopă?","options":[{"id":"A","text":"Unui pacient conștient i se administrează o băutură dulce pentru a preveni hipoglicemia."},{"id":"B","text":"Se administrează 1mg de glucagon intramuscular indiferent de starea de conștiență a pacientului."},{"id":"C","text":"Pacientul trebuie așezat în poziția Trendelenburg."},{"id":"D","text":"La un pacient inconștient, se poate administra soluție de glucoză 36-50% intravenos."},{"id":"E","text":"Se administrează soluție salină 10-20 ml/kg corp în prima oră pentru stabilizare."}],"correct":["A","C","D"],"pages":[438],"source":"set-2"},{"id":"set2-8gI3Dg4T","fingerprint":"ce3e87f672a827f0","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce semne și simptome sunt caracteristice fazei ulterioare a unei sincope?","options":[{"id":"A","text":"Polidipsie și poliurie."},{"id":"B","text":"Bradicardie și puls slab."},{"id":"C","text":"Tremor și senzație de foame."},{"id":"D","text":"Dilatarea pupilară și dezorientare."},{"id":"E","text":"Respirație neregulată sau absentă."}],"correct":["B","D","E"],"pages":[438],"source":"set-2"},{"id":"set2--9IwWj4d","fingerprint":"06be1ec25f3e4191","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele manifestări clinice sunt asociate cu hipoglicemia?","options":[{"id":"A","text":"Respirație cu miros de acetonă."},{"id":"B","text":"Hiperventilație și eritem facial."},{"id":"C","text":"Convulsii și paloare."},{"id":"D","text":"Tremor, palpitații și anxietate."},{"id":"E","text":"Dureri de cap, oboseală și tulburări de conștiență."}],"correct":["C","D","E"],"pages":[438],"source":"set-2"},{"id":"set2-zO8J2Oiq","fingerprint":"ae32c1e387ab3332","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"În cazul unui pacient cu hipoglicemie ale cărui simptome nu dispar după administrarea repetată de carbohidrați pe cale orală, care este o măsură terapeutică indicată?","options":[{"id":"A","text":"Administrarea unei soluții saline 10-20 ml/kg corp."},{"id":"B","text":"Administrarea de insulină intravenoasă pentru a stabiliza nivelul glicemiei."},{"id":"C","text":"Administrarea a 50 ml de dextroză 50% intravenos timp de 2-3 minute."},{"id":"D","text":"Poziționarea pacientului în Trendelenburg pentru a crește fluxul sanguin cerebral."},{"id":"E","text":"Continuarea administrării de zahăr dizolvat în apă la fiecare 20 de minute."}],"correct":["C"],"pages":[438],"source":"set-2"},{"id":"set2-x8f2-ew2","fingerprint":"38f1e4ed75d690ad","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele semne și simptome sunt caracteristice cetoacidozei diabetice?","options":[{"id":"A","text":"Tremor și senzație de foame."},{"id":"B","text":"Greață, vărsături și slăbiciune."},{"id":"C","text":"Bradicardie și scăderea tensiunii arteriale."},{"id":"D","text":"Hiperventilație și respirație cu miros de acetonă."},{"id":"E","text":"Polifagie, poliurie și polidipsie."}],"correct":["B","D","E"],"pages":[438],"source":"set-2"},{"id":"set2-eedkmB4v","fingerprint":"58842c97f28c49ae","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este secvența corectă a tratamentului pentru cetoacidoza diabetică?","options":[{"id":"A","text":"Se administrează insulină intravenoasă imediat, urmată de soluție salină după 2 ore."},{"id":"B","text":"Se administrează simultan insulină intravenoasă și soluție salină."},{"id":"C","text":"Se administrează soluție salină 10-20 ml/kg corp în prima oră, urmată de insulină intravenoasă după 2 ore."},{"id":"D","text":"Se administrează carbohidrați pe cale orală, urmați de insulină la 10 minute."},{"id":"E","text":"Se administrează 1 mg de glucagon intramuscular, urmat de soluție salină."}],"correct":["C"],"pages":[438],"source":"set-2"},{"id":"set2-JhVADzlt","fingerprint":"e6e38d11a4fdbe18","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care dintre următoarele manifestări ale unei reacții anafilactice sunt de natură cardiovasculară?","options":[{"id":"A","text":"Tuse, presiune toracică și dispnee."},{"id":"B","text":"Palpitații, tahicardie și șoc."},{"id":"C","text":"Crampe, dureri abdominale și diaree."},{"id":"D","text":"Anxietate, acufene și vertij."},{"id":"E","text":"Erupții cutanate, eritem și prurit."}],"correct":["B"],"pages":[438],"source":"set-2"},{"id":"set2-tGpNboYn","fingerprint":"d36b2cc66f074e41","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce semne specifice cutanate și la nivelul mucoaselor pot apărea în cadrul unei reacții anafilactice?","options":[{"id":"A","text":"Angioedem în regiunea periorbitală și periorală."},{"id":"B","text":"Respirație cu miros de acetonă."},{"id":"C","text":"Paloare și transpirații reci."},{"id":"D","text":"Eritem facial izolat."},{"id":"E","text":"Erupții cutanate, eritem și prurit."}],"correct":["A","E"],"pages":[438],"source":"set-2"},{"id":"set2-WEjtwUpd","fingerprint":"0fb52959c9ea702e","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt afirmațiile adevărate cu privire la mecanismul reacțiilor anafilactice acute?","options":[{"id":"A","text":"Reacția anafilactică se dezvoltă întotdeauna în câteva secunde de la reexpunere."},{"id":"B","text":"În perioada latentă de după prima expunere, mastocitele și bazofilele sunt sensibilizate."},{"id":"C","text":"Eliberarea histaminei are loc la prima expunere la antigen."},{"id":"D","text":"Reexpunerea la antigen determină eliberarea de histamină și amine vasoactive."},{"id":"E","text":"Stimularea sistemului imunitar de către antigen duce la formarea de anticorpi de tip IgE."}],"correct":["B","D","E"],"pages":[439],"source":"set-2"},{"id":"set2-1QwzBxCA","fingerprint":"0487ceb582f5d608","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Unui copil cu o greutate de 20 kg, care dezvoltă o reacție anafilactică, i se administrează adrenalină (epinefrină) subcutanat. Care este doza corectă din soluția 1:1000?","options":[{"id":"A","text":"0,2 ml"},{"id":"B","text":"0,01 ml"},{"id":"C","text":"0,1 ml"},{"id":"D","text":"0,25 ml"},{"id":"E","text":"2,0 ml"}],"correct":["A"],"pages":[439],"source":"set-2"},{"id":"set2-j-dhCVqN","fingerprint":"c88fc303051c7f23","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce fază a unei crize epileptice de tip grand mal se manifestă prin pierderea conștienței urmată de contracția musculaturii și are o durată de 10-20 secunde?","options":[{"id":"A","text":"Faza post-ictus"},{"id":"B","text":"Faza de incontinență"},{"id":"C","text":"Aura"},{"id":"D","text":"Faza ictus"},{"id":"E","text":"Faza clonică"}],"correct":["D"],"pages":[439],"source":"set-2"},{"id":"set2-loc9Wyk-","fingerprint":"356bb85bbd973a34","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele măsuri sunt indicate în gestionarea unui pacient care dezvoltă o criză epileptică în cabinetul stomatologic?","options":[{"id":"A","text":"Pacientul trebuie constrâns ferm pentru a limita mișcările convulsive."},{"id":"B","text":"Se solicită o ambulanță dacă criza durează mai mult de 3 minute."},{"id":"C","text":"Se îndepărtează toate instrumentele de lucru din cavitatea bucală."},{"id":"D","text":"Se introduc degetele în gura pacientului pentru a preveni lezarea țesuturilor moi."},{"id":"E","text":"Pacientul se așează culcat pe o parte pentru a reduce riscul de aspirare."}],"correct":["B","C","E"],"pages":[439],"source":"set-2"},{"id":"set2-r-A950sG","fingerprint":"10b706227cc37f68","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Pentru administrarea intravenoasă la copii în cazul unei reacții anafilactice, care este diluția corectă a adrenalinei și doza recomandată?","options":[{"id":"A","text":"Diluție 1:1000, doza de 0,1 ml/kg"},{"id":"B","text":"Diluție 1:10000, doza de 0,25 ml/an de vârstă"},{"id":"C","text":"Diluție 1:1000, doza de 0,01 ml/kg"},{"id":"D","text":"Diluție 1:10000, doza de 0,1 ml/kg"},{"id":"E","text":"Diluție 1:10000, preparată prin adăugarea a 1 ml soluție salină la 9 ml diluție originală"}],"correct":["D"],"pages":[439],"source":"set-2"},{"id":"set2-qpISmZ-6","fingerprint":"ddf8cdc11e1b4b39","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică farmacologică recomandată în cabinetul stomatologic dacă o criză epileptică se prelungește peste 5 minute?","options":[{"id":"A","text":"Se administrează adrenalină subcutanat în doză de 0,01 ml/kg."},{"id":"B","text":"Se administrează hidrocortizon intravenos în doză de 4 mg/kg."},{"id":"C","text":"Se administrează agoniști beta-2 în inhalație."},{"id":"D","text":"Se administrează difenhidramină 1-2 mg/kg intravenos lent."},{"id":"E","text":"Se administrează diazepam intravenos în doză de 0,25 mg/kg."}],"correct":["E"],"pages":[439],"source":"set-2"},{"id":"set2-uGwB_Mh4","fingerprint":"823ab1fc4dadc396","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Pe lângă adrenalină, ce alte opțiuni terapeutice sunt indicate în tratamentul de urgență al reacției anafilactice la copii?","options":[{"id":"A","text":"Antihistaminice pe cale parenterală, precum difenhidramina."},{"id":"B","text":"Diazepam intravenos pentru a controla simptomele neurologice."},{"id":"C","text":"Agoniști beta-2 în inhalație, în prezența bronhospasmului."},{"id":"D","text":"Corticosteroizi intravenos, precum metilprednisolon sau hidrocortizon."},{"id":"E","text":"Oxigen, în caz de simptome respiratorii sau hipotensiune arterială."}],"correct":["A","C","D","E"],"pages":[439],"source":"set-2"},{"id":"set2-LR_f1OHH","fingerprint":"88fc7ade6447d8a3","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt semnele și simptomele caracteristice fazei de excitație a unei reacții toxice la anestezicele locale?","options":[{"id":"A","text":"Reducerea tensiunii arteriale, a frecvenței cardiace și respiratorii."},{"id":"B","text":"Nistagmus, dureri de cap și tinitus."},{"id":"C","text":"Absența tusei și a expectorației."},{"id":"D","text":"Hipertensiune arterială, bătăi rapide ale inimii și respirație accelerată."},{"id":"E","text":"Vorbire neclară, tremor la nivelul feței și membrelor."}],"correct":["B","D","E"],"pages":[440],"source":"set-2"},{"id":"set2-Q3iLkGFY","fingerprint":"d3ebbfe104359ae7","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce măsuri sunt indicate în cabinetul stomatologic în cazul unui pacient care prezintă o reacție toxică la anestezicele locale?","options":[{"id":"A","text":"Asigurarea permeabilității căilor respiratorii pentru a facilita respirația normală."},{"id":"B","text":"Asigurarea furnizării de oxigen în cazul convulsiilor tonico-clonice pentru a preveni acidoza."},{"id":"C","text":"Așezarea pacientului în poziție de clinostatism și verificarea circulației și respirației."},{"id":"D","text":"Solicitarea imediată a ambulanței la primul semn de tremor."},{"id":"E","text":"Administrarea de aspirină pentru a controla hipertensiunea arterială."}],"correct":["A","B","C"],"pages":[440],"source":"set-2"},{"id":"set2-d_ZJLTcA","fingerprint":"dcd78e34db1e7192","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele recomandări trebuie respectate în abordarea unui copil cu astm bronșic în cabinetul stomatologic?","options":[{"id":"A","text":"Se vor utiliza cu precădere anestezice locale cu vasoconstrictoare pentru a limita absorbția sistemică."},{"id":"B","text":"Este indicat să se evite antiinflamatoarele de tipul aspirinei."},{"id":"C","text":"Tratamentele dentare trebuie temporizate dacă copilul prezintă wheezing."},{"id":"D","text":"Medicația de fond pentru astm trebuie întreruptă cu 24 de ore înainte de vizita la stomatolog."},{"id":"E","text":"Se recomandă reducerea stresului prin ședințe scurte și pregătire psihologică."}],"correct":["B","C","E"],"pages":[440],"source":"set-2"},{"id":"set2-k56TkpCl","fingerprint":"3423201474ae6812","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt caracteristicile tabloului clinic al stadiului cel mai sever al crizei acute de astm?","options":[{"id":"A","text":"Cianoză și torace imobil."},{"id":"B","text":"Absența tusei și a expectorației."},{"id":"C","text":"Hipotensiune arterială și tremor la nivelul feței."},{"id":"D","text":"Dispnee predominant expiratorie, wheezing și tahicardie."},{"id":"E","text":"Tuse uscată, cefalee și agitație."}],"correct":["A","B","D"],"pages":[440],"source":"set-2"},{"id":"set2-q3UKBY25","fingerprint":"d208349fed8be485","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce factori sunt considerați a fi stimuli extrinseci care pot declanșa criza de astm bronșic?","options":[{"id":"A","text":"Infecțiile și bronșita cronică."},{"id":"B","text":"Praful, aerul rece și polenul."},{"id":"C","text":"Efortul fizic și expunerea la ceață."},{"id":"D","text":"Stresul și sinuzita."},{"id":"E","text":"Părul de animal, anumite alimente și medicamente precum aspirina."}],"correct":["B","E"],"pages":[440],"source":"set-2"},{"id":"set2-h_x-scqW","fingerprint":"5d5569ab1657391e","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt măsurile corecte de management pentru un pacient după ce și-a revenit dintr-o criză epileptică în cabinetul stomatologic?","options":[{"id":"A","text":"Pacientul va pleca acasă însoțit de părinți sau aparținători."},{"id":"B","text":"Pacientul nu are permisiunea de a părăsi cabinetul până la restabilirea completă a stării de conștiență."},{"id":"C","text":"Pacientul va părăsi cabinetul neînsoțit, dacă se poate deplasa singur."},{"id":"D","text":"Se așează pacientul în poziție de clinostatism și se administrează oxigen."},{"id":"E","text":"Se va efectua o examinare a cavității bucale pentru a identifica eventuale leziuni noi."}],"correct":["A","B","E"],"pages":[440],"source":"set-2"},{"id":"set2-jhQzrCuw","fingerprint":"1b4623074529e0d6","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele măsuri sunt indicate în managementul unui atac de astm ușor survenit în timpul unui tratament dentar la un copil?","options":[{"id":"A","text":"Administrarea imediată de epinefrină intramuscular, în doză de 0,01-0,03 ml/kg."},{"id":"B","text":"Inițierea administrării unui corticosteroid, precum Prednison, ca primă linie de tratament."},{"id":"C","text":"Așezarea copilului în decubit dorsal pentru a facilita respirația."},{"id":"D","text":"Administrarea de Salbutamol spray, 2 pulverizări la fiecare 20 de minute, până la un total de 6 pulverizări într-o oră."},{"id":"E","text":"Întreruperea imediată a tratamentului dentar."}],"correct":["D","E"],"pages":[441],"source":"set-2"},{"id":"set2-Nx8BdUMR","fingerprint":"078017ed83398e9d","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce intervenție specifică este recomandată pentru un copil care dezvoltă un atac de astm sever în cabinetul stomatologic?","options":[{"id":"A","text":"Administrarea de Bricanyl spray, 6 pulverizări într-o singură doză."},{"id":"B","text":"Administrarea de epinefrină în doză de 0,01-0,03 ml/kg, soluție 1:1000, pe cale intramusculară sau subcutanată."},{"id":"C","text":"Administrarea de Prednison în doză de 0,1-0,2 mg/kg/zi."},{"id":"D","text":"Solicitarea ambulanței doar dacă pacientul își pierde conștiența."},{"id":"E","text":"Monitorizarea exclusivă a frecvenței respiratorii, fără administrare de medicamente."}],"correct":["B"],"pages":[441],"source":"set-2"},{"id":"set2-fapvt1WU","fingerprint":"e2fc21b71078a523","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect semnele clinice ale obstrucției căilor aeriene superioare la un copil în timpul tratamentului dentar?","options":[{"id":"A","text":"Starea de șoc poate apărea ca urmare a obstrucției căilor aeriene superioare provocate de un corp străin."},{"id":"B","text":"O tuse iritativă este un semn caracteristic al obstrucției căilor aeriene superioare cauzată de sedare."},{"id":"C","text":"Dispneea și cianoza sunt semne comune atât obstrucției prin sedare, cât și celei prin corp străin."},{"id":"D","text":"Hipoxemia, dispneea și cianoza sunt semne clinice specifice obstrucției cauzate de un corp străin."},{"id":"E","text":"Obstrucția căilor aeriene superioare poate fi cauzată atât de sedare, cât și de acțiunea unui corp străin."}],"correct":["A","C","E"],"pages":[441],"source":"set-2"},{"id":"set2-T-rk-TGk","fingerprint":"1795b592027513d0","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce măsuri preventive sunt menționate pentru a evita obstrucția căilor aeriene superioare în timpul tratamentului stomatologic la copii?","options":[{"id":"A","text":"Monitorizarea constantă a pulsului."},{"id":"B","text":"Administrarea profilactică a unui bronhodilatator."},{"id":"C","text":"Administrarea unei doze corecte de sedative."},{"id":"D","text":"Poziționarea copilului exclusiv în decubit dorsal."},{"id":"E","text":"Utilizarea sistematică a digii dentare."}],"correct":["C","E"],"pages":[441],"source":"set-2"},{"id":"set2-Xf42kiI0","fingerprint":"5280bde2e37baf72","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele aspecte descriu corect epidemiologia și etiologia traumatismelor dento-parodontale la nivelul dinților temporari?","options":[{"id":"A","text":"Dinții cel mai frecvent afectați sunt incisivii centrali maxilari."},{"id":"B","text":"Accidentele auto din cauza lipsei scaunului de copii reprezintă o cauză etiologică des întâlnită."},{"id":"C","text":"Molarii sunt frecvent implicați în aceste traumatisme prin mecanism direct."},{"id":"D","text":"Afectarea băieților este de două ori mai frecventă comparativ cu cea a fetelor."},{"id":"E","text":"Perioada de maximă incidență a acestor leziuni este în jurul vârstei de 5-10 ani."}],"correct":["A","B","D"],"pages":[427],"source":"set-2"},{"id":"set2-VajF5tBI","fingerprint":"ad6e1d4138f27a11","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele elemente anatomice contribuie la predominanța luxațiilor în fața fracturilor dentare la nivelul dinților temporari?","options":[{"id":"A","text":"Existența unui parodonțiu cu fibre foarte rigide."},{"id":"B","text":"Forma scurtă și globuloasă a coroanelor dentare."},{"id":"C","text":"Structura laxă a osului maxilar."},{"id":"D","text":"Rădăcinile care se află în proces de resorbție."},{"id":"E","text":"Coroanele dentare alungite și efilate, specifice dentiției primare."}],"correct":["B","C","D"],"pages":[427],"source":"set-2"},{"id":"set2-gqzgMl3V","fingerprint":"ec06df64e29656c5","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este forma clinică specifică de traumatism în cazul dinților temporari?","options":[{"id":"A","text":"Luxația laterală cu fractură alveolară."},{"id":"B","text":"Avulsia dentară completă."},{"id":"C","text":"Fractura radiculară în treimea apicală."},{"id":"D","text":"Fractura coronară cu deschiderea camerei pulpare."},{"id":"E","text":"Luxația cu intruzie."}],"correct":["E"],"pages":[427],"source":"set-2"},{"id":"set2-b4EwYwv7","fingerprint":"2b9fdba9bc23978b","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt măsurile terapeutice și recomandările adecvate în prima ședință de urgență pentru un traumatism dento-parodontal la dinții temporari?","options":[{"id":"A","text":"Efectuarea unei toalete sumare a plăgilor muco-gingivale."},{"id":"B","text":"Prescrierea unei alimentații moi, păstoase, pe o perioadă de o săptămână."},{"id":"C","text":"Imobilizarea dinților temporari foarte mobili cu atele compozite."},{"id":"D","text":"Extracția dinților temporari care prezintă o mobilitate foarte mare."},{"id":"E","text":"Reevaluarea clinică și radiologică la un interval de o lună de la traumatism."}],"correct":["A","B","D"],"pages":[427],"source":"set-2"},{"id":"set2-ihnLjL1i","fingerprint":"3d9b7a3a6efe56c1","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Din ce motive reprezintă o urgență majoră traumatismele dento-parodontale ale dinților temporari în medicina dentară pediatrică?","options":[{"id":"A","text":"Produc invariabil anchiloza dintelui temporar în alveolă."},{"id":"B","text":"Pot afecta structura și morfologia corono-radiculară a mugurilor dinților succesionali."},{"id":"C","text":"Pot influența negativ procesul de erupție pe arcada dentară a dinților succesionali."},{"id":"D","text":"Determină frecvent fracturi cominutive ale osului maxilar."},{"id":"E","text":"Implică un risc ridicat de sângerare pulpară imposibil de oprit."}],"correct":["B","C"],"pages":[427],"source":"set-2"},{"id":"set2-OOP-gHDm","fingerprint":"37be61e6fd46f3b0","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt atitudinile terapeutice indicate în cazul fracturilor coronare complicate la dinții temporari, în funcție de stadiul de dezvoltare și vechimea traumatismului?","options":[{"id":"A","text":"Extracția dintelui este recomandată dacă acesta se află în stadiul 3 de dezvoltare."},{"id":"B","text":"Pulpectomia devitală se indică la dinții în stadiul 2 cu traumatism mai vechi, dacă minim un sfert din rădăcină este prezentă."},{"id":"C","text":"Pulpectomia devitală se recomandă la dinții în stadiul 2 cu traumatism vechi, cu condiția ca trei sferturi din rădăcină să fie prezente."},{"id":"D","text":"Pulpotomia vitală este recomandată pentru dinții în stadiul 1 sau 2 de dezvoltare cu o fractură recentă."},{"id":"E","text":"Controlul periodic în cazul acestor fracturi se realizează doar la 6-8 săptămâni și la 1 an."}],"correct":["A","C","D"],"pages":[428],"source":"set-2"},{"id":"set2-tlghyk7Q","fingerprint":"e2636084299cfac6","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt pașii terapeutici recomandați în cazul fracturilor coronare necomplicate care implică atât smalțul, cât și dentina?","options":[{"id":"A","text":"Restaurarea finală implică utilizarea unei cape și a unui compozit sau a coroanelor de zirconiu."},{"id":"B","text":"Sigilarea dentinei expuse se face folosind ciment ionomer de sticlă fotopolimerizabil."},{"id":"C","text":"Se realizează control clinic și radiologic exclusiv la intervalul de 3-4 săptămâni."},{"id":"D","text":"Curățarea dentinei se realizează cu ser fiziologic, iar dezinfectarea cu hipoclorit de sodiu."},{"id":"E","text":"Restaurarea finală se obține prin aplicarea unor fațete ceramice pe dinții temporari afectați."}],"correct":["A","B","D"],"pages":[428],"source":"set-2"},{"id":"set2-j5E1LstE","fingerprint":"ad03532c12e52960","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații referitoare la atitudinea terapeutică și evoluția clinică în fracturile radiculare și corono-radiculare sunt adecvate?","options":[{"id":"A","text":"Prezentarea pacientului la câteva zile după un traumatism corono-radicular evidențiază frecvent un polip interfragmentar cu rol de protecție."},{"id":"B","text":"Fracturile corono-radiculare cu implicare radiculară redusă impun extracția dintelui temporar din cauza complicațiilor pe termen lung."},{"id":"C","text":"Fracturile radiculare localizate în treimea cervicală și medie beneficiază de imobilizare cu șină din compozit pentru 4 săptămâni."},{"id":"D","text":"Fracturile radiculare localizate în treimea medie se monitorizează la 2-3 săptămâni clinic și la 6-8 săptămâni radiologic."},{"id":"E","text":"În fracturile radiculare localizate în treimea apicală, fragmentul apical radicular se va resorbi concomitent cu erupția dintelui permanent."}],"correct":["A","E"],"pages":[428],"source":"set-2"},{"id":"set2-FkKaLlHr","fingerprint":"9b6602246d29c218","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce proceduri fac parte din abordarea terapeutică a fracturilor dento-alveolare în care sunt prezenți dinți foarte mobili?","options":[{"id":"A","text":"Imobilizarea cu șină de compozit a tuturor dinților foarte mobili până la exfolierea lor naturală."},{"id":"B","text":"Amputarea vitală a dinților implicați urmată de aplicarea unor coroane de zirconiu."},{"id":"C","text":"Secționarea coroanei dintelui foarte mobil la nivelul rebordului alveolar și sutura fragmentului osos vestibular."},{"id":"D","text":"Repoziționarea dinților, imobilizarea cu șină de acrilat pe o perioadă de 6 săptămâni și sutură."},{"id":"E","text":"Extracția dinților temporari mobili și conservarea osului alveolar restant fără intervenții chirurgicale suplimentare."}],"correct":["C"],"pages":[429],"source":"set-2"},{"id":"set2-m-vLhj9y","fingerprint":"38f117e05541473b","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele leziuni sunt incluse în categoria traumatismelor localizate la nivelul țesuturilor de susținere?","options":[{"id":"A","text":"Luxațiile"},{"id":"B","text":"Fracturile dento-alveolare"},{"id":"C","text":"Subluxația"},{"id":"D","text":"Fracturile corono-radiculare"},{"id":"E","text":"Contuzia"}],"correct":["A","C","E"],"pages":[429],"source":"set-2"},{"id":"set2-k1G1cc42","fingerprint":"f7889a3ab7c96833","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt caracteristicile clinice, radiologice și terapeutice specifice luxației cu intruzie la nivelul dentiției temporare?","options":[{"id":"A","text":"Este cea mai frecventă formă clinică de traumatism întâlnită la dinții temporari."},{"id":"B","text":"Prezența unui aspect elongat pe radiografie impune o atitudine de expectativă timp de 2-4 săptămâni."},{"id":"C","text":"Este traumatismul care se soldează cel mai frecvent cu apariția necrozei și a anchilozei dentare."},{"id":"D","text":"Dintele traumatizat prezintă mobilitate accentuată imediat după accident."},{"id":"E","text":"La percuție apare un sunet metalic determinat de contactul direct dintre rădăcină și osul alveolar."}],"correct":["A","C","E"],"pages":[429],"source":"set-2"},{"id":"set2-qSTJgT4D","fingerprint":"be21b2b9699f6629","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este atitudinea terapeutică de elecție pentru luxația orală a unui dinte temporar superior?","options":[{"id":"A","text":"Repoziționarea imediată și imobilizarea obligatorie prin sisteme fixe pentru o perioadă de 7-14 zile."},{"id":"B","text":"Expectativă, cu repoziționare treptată a dintelui sub acțiunea forței exercitate de orbicularul buzei."},{"id":"C","text":"Extracția dintelui traumatizat, motivată de afectarea invariabilă a mugurelui dintelui permanent."},{"id":"D","text":"Expectativă timp de 2-4 săptămâni până la reluarea erupției spontane a dintelui."},{"id":"E","text":"Repoziționarea manuală imediată sub anestezie loco-regională sau topică, urmată la nevoie de sutură gingivală."}],"correct":["E"],"pages":[430],"source":"set-2"},{"id":"set2-y3138Lf3","fingerprint":"04a242d9f8e4e0dc","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Referitor la complicațiile apărute consecutiv traumatismelor dinților temporari, care sunt asocierile clinico-evolutive caracteristice?","options":[{"id":"A","text":"Metamorfoza calcică determină un aspect gălbui al coroanei, fiind o complicație care oprește procesul fiziologic de rizaliză."},{"id":"B","text":"Anchiloza dentară rezultă din fuziunea dintre rădăcină și osul alveolar, fenomen ce conduce clinic la o suprapoziție a dintelui."},{"id":"C","text":"Necroza pulpară induce un aspect gri-cenușiu al coroanei la 3-4 săptămâni distanță de la producerea leziunii."},{"id":"D","text":"Hemoragia pulpară se obiectivează clinic prin modificarea culorii coroanei la 1-2 zile de la traumatism."},{"id":"E","text":"Afectarea mugurelui dintelui succesional este o complicație observată preponderent consecutiv luxațiilor cu intruzie."}],"correct":["C","D","E"],"pages":[431],"source":"set-2"},{"id":"set2-sAzDjea5","fingerprint":"fe48b12700fe7de4","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Prin ce se caracterizează contuzia și subluxația dinților temporari din punct de vedere clinic și terapeutic?","options":[{"id":"A","text":"Contuzia se asociază invariabil cu un grad redus de mobilitate dentară decelabilă clinic."},{"id":"B","text":"În cazul subluxației se observă clinic sângerare gingivală, sensibilitate la percuție și mobilitate, fără ca dintele să prezinte deplasare."},{"id":"C","text":"Subluxația implică ruperea completă a fibrelor ligamentare, ceea ce determină o mobilitate accentuată a dintelui."},{"id":"D","text":"Managementul ambelor traumatisme include repaus alimentar sau o alimentație moale timp de o săptămână și monitorizare periodică."},{"id":"E","text":"Inflamația ligamentului parodontal prezentă în contuzie generează clinic sensibilitate la percuția în ax sau în ocluzie."}],"correct":["B","D","E"],"pages":[429],"source":"set-2"},{"id":"set2-HKMm1lTu","fingerprint":"8e87f164e923090c","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt elementele definitorii de management terapeutic și diagnostic în luxația cu extruzie și în avulsia traumatică a dinților temporari?","options":[{"id":"A","text":"Tabloul clinic de avulsie traumatică necesită o validare obligatorie prin examinări radiologice specifice, inclusiv radiografie toracică."},{"id":"B","text":"Reimplantarea dintelui avulsat nu se recomandă în dentiția temporară din cauza riscului de lezare a mugurelui succesional."},{"id":"C","text":"Extruzia dentară caracterizată printr-o mobilitate redusă impune repoziționarea sub anestezie și imobilizarea timp de 7-14 zile."},{"id":"D","text":"Extracția reprezintă atitudinea de elecție pentru luxația cu extruzie în cazurile în care dintele nu prezintă nicio mobilitate clinică."},{"id":"E","text":"Luxația cu extruzie se distinge prin împingerea dintelui în interiorul alveolei și dispariția parțială sau totală a coroanei de pe arcadă."}],"correct":["A","B","C"],"pages":[430],"source":"set-2"},{"id":"set2-cTOZyefj","fingerprint":"8e5b1a2d64730919","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următorii factori sunt asociați cu epidemiologia și predispoziția traumatismelor dento-parodontale la dinții permanenți?","options":[{"id":"A","text":"Vârsta cuprinsă între 8 și 10 ani."},{"id":"B","text":"Prezența anomaliei dento-maxilare de clasa II/1 Angle."},{"id":"C","text":"Preponderența afectării pacienților proveniți din mediul urban."},{"id":"D","text":"Raportul coroană-rădăcină crescut, caracteristic dinților permanenți afectați."},{"id":"E","text":"Predilecția pentru sexul masculin, cu un raport de 2:1 comparativ cu sexul feminin."}],"correct":["A","B","E"],"pages":[431],"source":"set-2"},{"id":"set2-s71UHB24","fingerprint":"8dc34d7f2e5f8547","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele leziuni traumatice sunt încadrate în clasificarea traumatismelor țesuturilor de susținere?","options":[{"id":"A","text":"Subluxația."},{"id":"B","text":"Contuzia."},{"id":"C","text":"Avulsia."},{"id":"D","text":"Fractura dento-alveolară."},{"id":"E","text":"Fisura de smalț."}],"correct":["A","B","C"],"pages":[431],"source":"set-2"},{"id":"set2-l1gSWze_","fingerprint":"ed8fdef0254b694a","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Ce indică rezultatul negativ la testul termic la rece și percuția pozitivă în cadrul examenului clinic al unui dinte permanent traumatizat?","options":[{"id":"A","text":"Percuția pozitivă indică instalarea inflamației ligamentului parodontal, iar lipsa răspunsului la testul termic poate fi consecința unui șoc traumatic."},{"id":"B","text":"Percuția pozitivă atestă absența inflamației, iar răspunsul negativ la testul termic este un indicator funcțional exclusiv al dinților maturi."},{"id":"C","text":"Ambele semne clinice certifică prezența unei avulsii dentare cu resorbție radiculară consecutivă."},{"id":"D","text":"Percuția pozitivă semnalează o fractură radiculară, în timp ce testul termic negativ confirmă ireversibil necroza pulpară."},{"id":"E","text":"Percuția pozitivă evidențiază o fractură corono-radiculară, iar testul termic la rece exclude prezența unui șoc traumatic."}],"correct":["A"],"pages":[432],"source":"set-2"},{"id":"set2-oSyNywP2","fingerprint":"813e49e60af2f53e","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"În cadrul evaluării clinice a unui pacient cu traumatisme dento-parodontale survenite în urma unui accident sever, ce asocieri între semnele clinice și leziunile osoase asociate sunt menționate?","options":[{"id":"A","text":"Echimoza din zona suborbitară asociată cu hemoragie conjunctivală arată prezența unei fracturi condiliene."},{"id":"B","text":"Echimoza localizată la nivelul bărbiei indică o fractură mandibulară."},{"id":"C","text":"Echimoza în regiunea mastoidă indică o fractură de bază de craniu."},{"id":"D","text":"Hemoragia din meatul auditiv extern indică o fractură zigomatică."},{"id":"E","text":"Hematomul sublingual sugerează o fractură mandibulară la nivelul simfizei mentoniere sau în regiunea canină."}],"correct":["B","C","E"],"pages":[433],"source":"set-2"},{"id":"set2-fKfuzzqN","fingerprint":"2744f751ca004cb7","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt particularitățile metodelor de investigație complementare recomandate la pacienții cu traumatisme dento-parodontale?","options":[{"id":"A","text":"Transiluminarea folosește lumina ultravioletă aplicată pe suprafața dentară dinspre oral pentru depistarea fisurilor dentare."},{"id":"B","text":"Examenul ORL este direct indicat la apariția unor simptome neurologice precum cefaleea, voma și letargia."},{"id":"C","text":"Radiografiile de torace sau abdomen se indică la pacienții inconștienți care prezintă dinți avulsionați."},{"id":"D","text":"Diagnosticul radiologic permite evaluarea precisă a gradului de resorbție și a nivelului de dezvoltare radiculară."},{"id":"E","text":"Examenul radiologic evidențiază traiectul fracturii radiculare, care poate fi exclusiv transversal sau oblic."}],"correct":["A","C","D"],"pages":[432],"source":"set-2"},{"id":"set2-Eny35IS2","fingerprint":"5f24bb0ea5b1012a","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"În managementul fracturilor coronare complicate la dinții permanenți imaturi, abordarea terapeutică variază în funcție de momentul prezentării și de dimensiunea expunerii pulpare. Care dintre următoarele principii clinice sunt valabile?","options":[{"id":"A","text":"Coafajul direct permite o conservare exclusiv parțială a țesutului pulpar, fiind rezervat traumatismelor vechi."},{"id":"B","text":"Coafajul direct este indicat pentru o expunere pulpară mai mică de 1 mm, în condițiile unei prezentări la cabinet în primele 1-6 ore de la traumatism."},{"id":"C","text":"Pulpotomia vitală parțială se realizează exclusiv în cazul expunerilor pulpare de peste 2 mm, indiferent de timpul scurs de la traumatism."},{"id":"D","text":"Pulpotomia vitală totală este tratamentul recomandat pentru traumatismele cu o vechime de 6-10 ore sau mai mult, caracterizate printr-o expunere pulpară de 1-2 mm."},{"id":"E","text":"În pulpotomia vitală parțială, îndepărtarea țesutului pulpar expus se efectuează sub irigare continuă, utilizând un excavator sau o freză rotundă diamantată."}],"correct":["B","D","E"],"pages":[434],"source":"set-2"},{"id":"set2-LeiJ0Orn","fingerprint":"f3be9d8e711d2590","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care dintre următoarele caracteristici descriu corect tabloul clinic, diagnosticul și elementele de prognostic ale fracturilor radiculare?","options":[{"id":"A","text":"Linia de fractură situată la nivelul treimii apicale se asociază clinic cu o mobilitate marcată și o deplasare evidentă a fragmentului coronar."},{"id":"B","text":"Cele mai multe fracturi radiculare au localizarea în treimea apicală, înregistrând o incidență crescută la nivelul incisivilor superiori."},{"id":"C","text":"Diagnosticul fracturilor radiculare cu localizare în treimea apicală este eminamente radiologic, stabilit prin evidențierea unei linii radiotransparente."},{"id":"D","text":"Prognosticul capătă un caracter favorabil în situația în care tratamentul de repoziționare are loc tardiv, iar apexul dentar este complet închis."},{"id":"E","text":"Instalarea primelor semne de necroză pulpară impune depulparea imediată și obligatorie a ambelor fragmente radiculare."}],"correct":["C"],"pages":[434],"source":"set-2"},{"id":"set2-wR5Bik_5","fingerprint":"2b83adf7d681ee69","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Conduita terapeutică în traumatismele de tipul fracturilor radiculare se adaptează manifestărilor clinice specifice. Care sunt intervențiile adecvate în acest context?","options":[{"id":"A","text":"În lipsa deplasării fragmentelor fracturate, protocolul impune aplicarea unei imobilizări funcționale semi-rigide pentru o durată de 4 luni."},{"id":"B","text":"Procesul de reparare tisulară este susținut prin utilizarea unei paste de hidroxid de calciu, aplicată la 4 săptămâni după tratamentul medicamentos inițial și înlocuită periodic."},{"id":"C","text":"Prezența mobilității însoțite de deplasarea fragmentului coronar necesită repoziționare imediată sub anestezie și o imobilizare rigidă întinsă pe o perioadă de 4 luni."},{"id":"D","text":"Apariția necrozei la nivelul fragmentului coronar impune depulparea acestuia și aplicarea inițială a unui preparat medicamentos ce asociază un antibiotic și un corticosteroid."},{"id":"E","text":"Depulparea preventivă se execută sistematic la toți dinții cu fracturi radiculare cu deplasare, în primele 24 de ore de la producerea traumatismului."}],"correct":["B","C","D"],"pages":[434],"source":"set-2"},{"id":"set2-xdq7sC0Q","fingerprint":"624709d647b0577b","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"În contextul fracturilor coronare necomplicate, extinse la nivelul smalțului și dentinei, ce obiective clinice și pași terapeutici se aplică în tratamentul dinților permanenți tineri?","options":[{"id":"A","text":"Tratamentul se finalizează prin efectuarea unei pulpotomii vitale parțiale, necesară stopării inflamației dentinare secundare."},{"id":"B","text":"Tehnica indicată pentru sigilarea canaliculelor expuse implică efectuarea imediată a unui coafaj direct, utilizând un compus pe bază de MTA."},{"id":"C","text":"Protecția pulpară se asigură prin efectuarea unui coafaj indirect, materialele de elecție fiind hidroxidul de calciu sau cimentul ionomer de sticlă."},{"id":"D","text":"Coafajul indirect va fi acoperit obligatoriu de o restaurare coronară provizorie sau de durată, confecționată din material compozit."},{"id":"E","text":"Obiectivul terapeutic major constă în protecția dentinei prin sigilarea canaliculelor dentinare, măsură esențială pentru păstrarea vitalității pulpare în vederea apexogenezei."}],"correct":["C","D","E"],"pages":[433],"source":"set-2"},{"id":"set2-4w0BqiOI","fingerprint":"6bcac3443872c962","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Opțiunile terapeutice în cazul fracturilor corono-radiculare sunt dictate de profunzimea liniei de fractură și de gradul de maturitate a rădăcinii dentare. Care sunt intervențiile corecte pentru aceste traumatisme?","options":[{"id":"A","text":"În cazul unui dinte imatur care a suferit pierderea vitalității pulpare ca urmare a traumatismului, se indică tehnica de apexificare pentru asigurarea sigilării endodontice la nivel apical."},{"id":"B","text":"Proceduri adjuvante precum gingivectomia, osteotomia și extruzia ortodontică sunt contraindicate absolut din cauza riscului de destabilizare radiculară severă."},{"id":"C","text":"Prezența liniei de fractură sub creasta alveolară la un dinte cu maturare radiculară completă impune rezecția fragmentului coronar și instituirea tratamentului endodontic complet."},{"id":"D","text":"Dacă linia de fractură este localizată deasupra crestei alveolare, iar dintele este matur, tratamentul de elecție implică realizarea apexificării radiculare."},{"id":"E","text":"Fractura necomplicată care se extinde deasupra marginii gingivale necesită în primă fază sigilarea dentinei expuse cu ciment ionomer de sticlă."}],"correct":["A","C","E"],"pages":[435],"source":"set-2"},{"id":"set2-LaaiguVg","fingerprint":"828213b6da9a9787","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele afirmații sunt corecte cu privire la subluxația dentară în practica pedodontică (indiferent dacă afectează dinți temporari sau permanenți)?","options":[{"id":"A","text":"Reprezintă un traumatism în care se produce mobilitate dentară fără deplasare."},{"id":"B","text":"Presupune o sensibilitate accentuată la percuție și sângerare la nivelul șanțului gingival."},{"id":"C","text":"Se caracterizează clinic printr-o lărgire semnificativă a spațiului periodontal vizibilă radiografic."},{"id":"D","text":"Permite realizarea diagnosticului diferențial radiologic cu o eventuală fractură radiculară."},{"id":"E","text":"Tratamentul implică obligatoriu imobilizarea dintelui pentru o perioadă minimă de 4 săptămâni."}],"correct":["A","B","D"],"pages":[435],"source":"set-2"},{"id":"set2-r1tfj7iT","fingerprint":"9336afa8476fa2eb","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"În cazul unui dinte care a suferit o luxație cu intruzie și prezintă o rădăcină complet formată, care sunt atitudinile terapeutice indicate?","options":[{"id":"A","text":"Se inițiază extruzia ortodontică imediată folosind forțe ușoare."},{"id":"B","text":"Se așteaptă reerupția spontană a dintelui pentru o perioadă de 2-3 săptămâni."},{"id":"C","text":"Se realizează depulparea urmată de tratament endodontic."},{"id":"D","text":"Se evită depulparea pentru a permite revascularizarea țesutului pulpar."},{"id":"E","text":"Se evită extruzia ortodontică pentru a preveni resorbția radiculară și anchiloza."}],"correct":["A","C"],"pages":[436],"source":"set-2"},{"id":"set2-w28Ta1Ky","fingerprint":"4a05bfa8a2a2e8b0","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care este conduita terapeutică adecvată în cazul avulsiei dentare, atunci când pacientul se prezintă pentru replantare tardiv, după 60 de minute de la producerea traumatismului?","options":[{"id":"A","text":"Dintele replantat va fi imobilizat pentru o perioadă de 14 zile."},{"id":"B","text":"Depulparea se realizează în aceeași ședință, concomitent cu replantarea dintelui în alveolă."},{"id":"C","text":"În cazul dinților foarte imaturi, depulparea este temporizată și se efectuează doar la primele semne de necroză."},{"id":"D","text":"Porțiunile necrozate ale ligamentului se îndepărtează utilizând obligatoriu instrumentar mecanic."},{"id":"E","text":"Dintele este menținut într-o soluție antiseptică sau cu antibiotice pentru o perioadă de 20 de minute."}],"correct":["A","C","E"],"pages":[437],"source":"set-2"},{"id":"set2-TxUB5sLw","fingerprint":"4be16710abbb1253","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele enunțuri descriu corect complicațiile ce pot apărea în urma traumatismelor la dinții permanenți?","options":[{"id":"A","text":"Resorbția radiculară externă are la bază un mecanism de declanșare inflamator și infecțios care induce apariția osteoclastelor."},{"id":"B","text":"Anchiloza dentară este semnalată clinic prin suprapoziția dintelui traumatizat raportat la planul de ocluzie."},{"id":"C","text":"Resorbția radiculară internă are un debut imediat, la 1-2 zile după un traumatism contuziv minor."},{"id":"D","text":"Hemoragia internă reprezintă o condiție reversibilă care modifică culoarea dintelui, dar nu necesită terapie pulpară."},{"id":"E","text":"Calcifierea țesutului pulpar se manifestă clinic prin apariția unei colorații galben-opace a coroanei dentare."}],"correct":["A","D","E"],"pages":[437],"source":"set-2"},{"id":"set2-XI_2MJp-","fingerprint":"ee791750de4a5b02","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la caracteristicile și managementul luxației laterale?","options":[{"id":"A","text":"Sistemul de imobilizare ales trebuie să se extindă pe 2-3 dinți de fiecare parte a zonei traumatizate."},{"id":"B","text":"Se asociază frecvent cu o mobilitate dentară severă constatată în cadrul examenului clinic."},{"id":"C","text":"La dinții imaturi se recomandă depulparea de necesitate în vederea prevenirii resorbției radiculare interne."},{"id":"D","text":"Presupune imobilizarea funcțională a dintelui pe o perioadă ce poate ajunge până la 8 săptămâni în cazul asocierii unei fracturi alveolare severe."},{"id":"E","text":"Sistemul de imobilizare aplicat trebuie să fie conceput astfel încât să nu producă disfuncții ocluzale."}],"correct":["A","D","E"],"pages":[436],"source":"set-2"},{"id":"set2-M0aON82y","fingerprint":"de2f38f93c8d9466","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele manifestări clinice și măsuri terapeutice caracterizează sincopa în cabinetul de medicină dentară?","options":[{"id":"A","text":"Pacientului inconștient i se administrează o băutură dulce per os pentru a preveni hipoglicemia."},{"id":"B","text":"Se recomandă așezarea pacientului în poziția Trendelenburg."},{"id":"C","text":"Inițial apar tahicardia și hipertensiunea arterială, urmate de transpirații reci."},{"id":"D","text":"La pacienții inconștienți se poate aplica miere în șanțul vestibular, evitând aspirația."},{"id":"E","text":"În faza avansată, pacientul prezintă bradicardie și scăderea tensiunii arteriale."}],"correct":["B","D","E"],"pages":[438],"source":"set-2"},{"id":"set2-O9UYKr3e","fingerprint":"7fcc94d662c45abc","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt etapele și măsurile indicate în managementul unui episod de hipoglicemie survenit în timpul tratamentului stomatologic la copil?","options":[{"id":"A","text":"Alternativa terapeutică pentru lipsa de răspuns la carbohidrații orali constă în administrarea a 50 ml de dextroză 50% intravenos timp de 2-3 minute."},{"id":"B","text":"În cazul persistenței simptomelor, se administrează 1 mg glucagon intravenos lent."},{"id":"C","text":"Se administrează carbohidrați pe cale orală, repetând doza la fiecare 10 minute până la dispariția simptomelor."},{"id":"D","text":"Copilul este așezat imediat în poziție Trendelenburg pentru a favoriza irigarea cerebrală."},{"id":"E","text":"Pacientul este așezat în poziție de ortostatism și se acordă atenție respirației și circulației."}],"correct":["A","C","E"],"pages":[439],"source":"set-2"},{"id":"set2-9H8ejTP2","fingerprint":"f2f88582fa5a2847","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Ce protocoale farmacologice și proceduri sunt indicate în tratamentul de urgență al reacției anafilactice la copil?","options":[{"id":"A","text":"Pacientul este așezat în poziție de ortostatism la primele semne ale reacției pentru a facilita respirația."},{"id":"B","text":"Epinefrina administrată intramuscular necesită o diluție de 1:10000, doza fiind de 0,25 ml/an de vârstă."},{"id":"C","text":"Inhalarea de agoniști beta-2 în caz de bronhospasm presupune administrarea a 2,5 mg pentru copiii cu vârsta de până la 5 ani."},{"id":"D","text":"Adrenalina administrată subcutanat se folosește în diluție 1:1000, în doză de 0,01 ml/kg corp."},{"id":"E","text":"Corticosteroizii recomandați sunt metilprednisolon în doză de 4 mg/kg sau hidrocortizon în doză de 1-2 mg/kg."}],"correct":["B","C","D"],"pages":[439],"source":"set-2"},{"id":"set2-uJYGmcSH","fingerprint":"d77ae34688330a37","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care sunt afirmațiile adevărate privind tabloul clinic și conduita terapeutică în cazul unei crize epileptice de tip grand mal?","options":[{"id":"A","text":"Fotoliul dentar se coboară cât mai aproape de podea, iar introducerea degetelor în cavitatea bucală a pacientului este interzisă."},{"id":"B","text":"Faza clonică durează între 10 și 20 de secunde și se caracterizează exclusiv prin pierderea conștienței și contracția inițială a musculaturii."},{"id":"C","text":"Pacientul trebuie așezat culcat pe o parte pentru a reduce riscul de aspirare a secrețiilor sau a materialelor dentare."},{"id":"D","text":"Faza numită ictus duce la pierderea conștienței urmată de contracția musculaturii, având o durată de 10-20 secunde."},{"id":"E","text":"Dacă criza durează mai mult de 3 minute, se administrează direct 0,25 mg/kg de diazepam intravenos."}],"correct":["A","C","D"],"pages":[439],"source":"set-2"},{"id":"set2-NFOx94dW","fingerprint":"75a36b611b045cb6","chapterId":"set-2","subchapterId":"set2-5.05","type":"CM","text":"Care dintre următoarele aspecte descriu corect simptomatologia și managementul astmului bronșic în practica pedodontică?","options":[{"id":"A","text":"Conduita de urgență în criza acută include așezarea copilului în poziție șezândă și administrarea unui bronhodilatator inhalator."},{"id":"B","text":"În atacurile severe se utilizează epinefrină în doză de 0,01-0,03 ml/kg, din soluția 1:1000, administrată intramuscular sau subcutanat."},{"id":"C","text":"Se evită utilizarea anestezicelor locale cu vasoconstrictor în tratamentul copiilor cu astm bronșic."},{"id":"D","text":"Medicația de fond a pacientului trebuie întreruptă temporar înainte de efectuarea tratamentelor dentare."},{"id":"E","text":"Criza acută de astm în stadiul cel mai sever se prezintă cu tuse abundentă, expectorație și dispnee predominant inspiratorie."}],"correct":["A","B","C"],"pages":[441],"source":"set-2"},{"id":"set2-NkMowYKs","fingerprint":"69f41790121b235a","chapterId":"set-2","subchapterId":"set2-5.05","type":"CS","text":"Care este secvența corectă a manifestărilor clinice și a complicațiilor potențiale în cadrul reacției toxice la anestezicele locale?","options":[{"id":"A","text":"Frecvența cardiacă și tensiunea arterială cresc în stadiul tardiv al reacției toxice, odată cu pierderea conștienței."},{"id":"B","text":"Tabloul clinic debutează prin depresia profundă a sistemului nervos central, manifestată prin hipotensiune și bradicardie."},{"id":"C","text":"Prima fază de excitație asociază hipertensiune arterială, tahicardie, respirație accelerată și posibil convulsii, urmată ulterior de depresia sistemului nervos central."},{"id":"D","text":"Absorbția lentă a anestezicului în fluxul sanguin previne instalarea tremorului și a nistagmusului."},{"id":"E","text":"Retenția de dioxid de carbon din timpul crizelor convulsive duce la instalarea alcalozei respiratorii."}],"correct":["C"],"pages":[440],"source":"set-2"}];
